// PERF: preconnect and dns-prefetch injected once at module level —
// avoids re-querying/creating DOM nodes on every page transition.
if (typeof document !== "undefined") {
	const addLink = (rel, href, crossOrigin) => {
		const sel = `link[rel="${rel}"][href="${href}"]`;
		if (!document.querySelector(sel)) {
			const el = document.createElement("link");
			el.rel = rel;
			el.href = href;
			if (crossOrigin !== undefined) el.crossOrigin = crossOrigin;
			document.head.appendChild(el);
		}
	};
	addLink("preconnect", "https://fonts.googleapis.com");
	addLink("preconnect", "https://fonts.gstatic.com", "");
	addLink("dns-prefetch", "https://api.whatsapp.com");
	addLink("dns-prefetch", "https://www.indiamart.com");
	// Hero image preload is injected conditionally in the App component
	// only when the user is on the homepage — see App() useEffect.

	// ── Security meta tags ──────────────────────────────────────────────────
	// Content-Security-Policy: restricts origins for scripts, styles, images,
	// frames, and API fetches. Adjust the nonce or hash approach if you later
	// adopt SSR. These are defence-in-depth on top of Cloudflare header rules;
	// ideally duplicate them as HTTP headers in _headers / wrangler.toml too.
	const addMeta = (httpEquiv, content) => {
		if (!document.querySelector(`meta[http-equiv="${httpEquiv}"]`)) {
			const m = document.createElement("meta");
			m.httpEquiv = httpEquiv;
			m.content = content;
			document.head.insertBefore(m, document.head.firstChild);
		}
	};
	addMeta(
		"Content-Security-Policy",
		[
			"default-src 'self'",
			// Scripts: self + Cloudflare Turnstile + GA4 + Clarity + Google Translate + inline event handlers
			"script-src 'self' 'unsafe-inline' https://challenges.cloudflare.com https://www.googletagmanager.com https://www.clarity.ms https://cdn.clarity.ms https://translate.googleapis.com https://translate.google.com",
			// Styles: self + Google Fonts + Google Translate + inline (Tailwind/CSS-in-JS)
			"style-src 'self' 'unsafe-inline' https://fonts.googleapis.com https://translate.googleapis.com",
			// Fonts
			"font-src 'self' https://fonts.gstatic.com",
			// Images: self + data URIs + Google Translate assets + CDN sources
			"img-src 'self' data: https: blob:",
			// Frames: Turnstile iframe + Google Maps embed + Google Translate
			"frame-src https://challenges.cloudflare.com https://maps.google.com https://www.google.com",
			// API fetches: Web3Forms, exchange rates, BigDataCloud geolocation, GA4, Google Translate
			"connect-src 'self' https://api.web3forms.com https://open.er-api.com https://api.bigdatacloud.net https://www.google-analytics.com https://region1.google-analytics.com https://www.clarity.ms https://translate.googleapis.com",
			// Tighten mixed-content + object/base
			"upgrade-insecure-requests",
			"object-src 'none'",
			"base-uri 'self'",
			"form-action 'self' https://api.web3forms.com",
		].join("; "),
	);
	// Referrer-Policy: send origin only for same-site; strip for cross-origin
	addMeta("referrer", "strict-origin-when-cross-origin");
	// Permissions-Policy: opt out of browser features the site doesn't use
	if (!document.querySelector('meta[name="permissions-policy"]')) {
		const pp = document.createElement("meta");
		pp.name = "permissions-policy";
		pp.content =
			"camera=(), microphone=(), geolocation=(), payment=(), usb=(), fullscreen=(self)";
		document.head.insertBefore(pp, document.head.firstChild);
	}
}

// ─── ANALYTICS: GA4 + Microsoft Clarity ──────────────────────
// IDs are read from Vite environment variables — never hardcoded.
// Set in Cloudflare Pages → Settings → Environment Variables:
//   VITE_GA4_ID     = G-XXXXXXXXXX   (Google Analytics 4 Measurement ID)
//   VITE_CLARITY_ID = XXXXXXXXXX     (Microsoft Clarity Project ID)
// For local dev, set these in your .env file at the project root.
//
const GA4_ID = import.meta.env.VITE_GA4_ID ?? "";
const CLARITY_ID = import.meta.env.VITE_CLARITY_ID ?? "";
// Cloudflare Turnstile site key — public, safe to bundle.
// Set VITE_TURNSTILE_SITE_KEY in .env / Cloudflare Pages env vars.
// Leave empty to disable the widget (forms still work, just without bot protection).
const TURNSTILE_SITE_KEY = import.meta.env.VITE_TURNSTILE_SITE_KEY ?? "";

// trackPageView is module-scoped so navigate() can call it
// directly on every pushState navigation — not just popstate (back/forward).
// path must be a clean pathname like '/products' or '/product/prod_ts1'.
const trackPageView = (path) => {
	if (typeof window.gtag === "function") {
		window.gtag("event", "page_view", {
			page_path: path,
			page_location: `${window.location.origin}/#${path}`,
			page_title: document.title,
		});
	}
};

if (typeof document !== "undefined") {
	// ── Google Analytics 4 ──────────────────────────────────────
	if (GA4_ID && !document.getElementById("ga4-script")) {
		const s1 = document.createElement("script");
		s1.id = "ga4-script";
		s1.src = `https://www.googletagmanager.com/gtag/js?id=${GA4_ID}`;
		s1.async = true;
		document.head.appendChild(s1);

		const s2 = document.createElement("script");
		s2.id = "ga4-init";
		// send_page_view:false — we fire all page_view events manually via
		// trackPageView() so there is no double-count on the initial load.
		s2.text =
			`window.dataLayer=window.dataLayer||[];` +
			`function gtag(){dataLayer.push(arguments);}` +
			`gtag('js',new Date());` +
			`gtag('config','${GA4_ID}',{send_page_view:false});`;
		document.head.appendChild(s2);

		// Fire the first page_view for the initial landing page
		// (deferred so gtag is defined before we call it)
		window.addEventListener(
			"load",
			() => {
				const initPath = window.location.hash.replace("#", "") || "/";
				trackPageView(initPath);
			},
			{ once: true },
		);

		// popstate fires on browser back/forward only.
		// NOTE: navigate() handles GA4 for pushState navigations (forward clicks).
		// DO NOT add trackPageView inside the App's popstate handler — it would double-fire.
		window.addEventListener("popstate", () => {
			const path = window.location.hash.replace("#", "") || "/";
			trackPageView(path);
		});
	}

	// ── Microsoft Clarity ───────────────────────────────────────
	if (CLARITY_ID && !document.getElementById("clarity-script")) {
		const cs = document.createElement("script");
		cs.id = "clarity-script";
		cs.type = "text/javascript";
		cs.text =
			`(function(c,l,a,r,i,t,y){c[a]=c[a]||function(){(c[a].q=c[a].q||[]).push(arguments)};` +
			`t=l.createElement(r);t.async=1;t.src="https://www.clarity.ms/tag/"+i;` +
			`y=l.getElementsByTagName(r)[0];y.parentNode.insertBefore(t,y);` +
			`})(window,document,"clarity","script","${CLARITY_ID}");`;
		document.head.appendChild(cs);
	}

	// ── Cloudflare Turnstile ─────────────────────────────────────
	// Script loaded once at module level so both forms can share it.
	if (TURNSTILE_SITE_KEY && !document.getElementById("cf-turnstile-script")) {
		const ts = document.createElement("script");
		ts.id = "cf-turnstile-script";
		ts.src = "https://challenges.cloudflare.com/turnstile/v0/api.js";
		ts.async = true;
		ts.defer = true;
		document.head.appendChild(ts);
	}
}

// Reusable Turnstile widget — renders only when TURNSTILE_SITE_KEY is set.
// onVerify(token) is called when the challenge is solved.
// onExpire() is called if the token expires before submission.
const TurnstileWidget = memo(({ onVerify, onExpire, widgetId }) => {
	const containerRef = useRef(null);
	const renderIdRef = useRef(null);
	// Store callbacks in refs so the effect never stales — without making them deps
	// (which would destroy and re-render the widget on every parent re-render).
	const onVerifyRef = useRef(onVerify);
	const onExpireRef = useRef(onExpire);
	useEffect(() => { onVerifyRef.current = onVerify; }, [onVerify]);
	useEffect(() => { onExpireRef.current = onExpire; }, [onExpire]);

	useEffect(() => {
		if (!TURNSTILE_SITE_KEY || !containerRef.current) return;

		const render = () => {
			if (!containerRef.current || !window.turnstile) return;
			// Avoid double-rendering if effect re-runs
			if (renderIdRef.current != null) return;
			renderIdRef.current = window.turnstile.render(containerRef.current, {
				sitekey: TURNSTILE_SITE_KEY,
				callback: (...args) => onVerifyRef.current?.(...args),
				"expired-callback": (...args) => onExpireRef.current?.(...args),
				theme: "light",
				size: "normal",
			});
		};

		if (window.turnstile) {
			render();
		} else {
			// Script not yet loaded — poll briefly
			const t = setInterval(() => {
				if (window.turnstile) {
					clearInterval(t);
					render();
				}
			}, 100);
			return () => clearInterval(t);
		}

		return () => {
			if (renderIdRef.current != null && window.turnstile) {
				window.turnstile.remove(renderIdRef.current);
				renderIdRef.current = null;
			}
		};
	}, [widgetId]); // widgetId change = remount the widget (e.g. after form reset)

	if (!TURNSTILE_SITE_KEY) return null;
	return <div ref={containerRef} className="mt-3" />;
});
TurnstileWidget.displayName = "TurnstileWidget";

// ─── SEO HEAD ─────────────────────────────────────────────────
const SITE_KEYWORDS =
	"turbine maintenance India, steam turbine overhauling, turbine reverse engineering, industrial turbine spares, lube oil filter elements, expansion joints India, Triveni turbine service, BHEL turbine spares, turbine erection Uttar Pradesh, Shamli engineering";

const SEOHead = memo(
	({
		title,
		description,
		schema,
		pageType,
		canonicalPath,
		publishedTime,
		noIndex,
	}) => {
		useEffect(() => {
			const fullTitle = title
				? `${title} | ${BRAND_NAME}`
				: `${BRAND_NAME} | ${BRAND_TAGLINE}`;
			const fullDesc =
				description ||
				`Precision turbine engineering, overhauling, reverse engineering, and OEM-compatible industrial spares — ${BRAND_NAME}, Shamli, UP, India.`;
			const canonical = canonicalPath
				? `${SITE_URL}${canonicalPath}`
				: SITE_URL;

			document.title = fullTitle;

			const sm = (sel, attr, val, content) => {
				let t = document.querySelector(sel);
				if (!t) {
					t = document.createElement("meta");
					t.setAttribute(attr, val);
					document.head.appendChild(t);
				}
				t.content = content;
			};
			const sl = (rel, href, attrs) => {
				const key = attrs?.as
					? `link[rel="${rel}"][as="${attrs.as}"][href="${href}"]`
					: `link[rel="${rel}"][href="${href}"]`;
				// Always match by the full key (rel + as + href) to avoid clobbering
				// a different preload/prefetch link that happens to share the same rel.
				let t = document.querySelector(key);
				if (!t) {
					t = document.createElement("link");
					t.rel = rel;
					document.head.appendChild(t);
				}
				t.href = href;
				if (attrs)
					Object.entries(attrs).forEach(([k, v]) => {
						if (k === "crossorigin") t.crossOrigin = v;
						else t.setAttribute(k, v);
					});
			};

			// ── Core meta ──
			sm('meta[name="description"]', "name", "description", fullDesc);
			sm('meta[name="keywords"]', "name", "keywords", SITE_KEYWORDS);
			sm(
				'meta[name="robots"]',
				"name",
				"robots",
				noIndex
					? "noindex, nofollow"
					: "index, follow, max-snippet:-1, max-image-preview:large, max-video-preview:-1",
			);
			sm('meta[name="author"]', "name", "author", BRAND_NAME);
			sm('meta[name="theme-color"]', "name", "theme-color", "#0A192F");

			// ── Canonical ──
			sl("canonical", canonical);

			// ── Viewport meta ──
			if (!document.querySelector('meta[name="viewport"]')) {
				const vm = document.createElement("meta");
				vm.name = "viewport";
				vm.content = "width=device-width, initial-scale=1, maximum-scale=5";
				document.head.appendChild(vm);
			}

			// ── LLM / AI Crawler Discovery (llms.txt standard) ──
			// Helps AI assistants (ChatGPT, Gemini, Claude, Perplexity) find structured content
			sl("help", `${SITE_URL}/llms.txt`, {
				type: "text/plain",
				title: "LLM-readable site summary",
			});
			sl("help", `${SITE_URL}/llms-full.txt`, {
				type: "text/plain",
				title: "LLM-readable full catalog",
			});

			// ── Open Graph ──
			sm('meta[property="og:title"]', "property", "og:title", fullTitle);
			sm(
				'meta[property="og:description"]',
				"property",
				"og:description",
				fullDesc,
			);
			sm(
				'meta[property="og:type"]',
				"property",
				"og:type",
				pageType === "article" ? "article" : "website",
			);
			sm('meta[property="og:url"]', "property", "og:url", canonical);
			sm('meta[property="og:image"]', "property", "og:image", OG_IMAGE);
			sm(
				'meta[property="og:image:width"]',
				"property",
				"og:image:width",
				"1200",
			);
			sm(
				'meta[property="og:image:height"]',
				"property",
				"og:image:height",
				"630",
			);
			sm(
				'meta[property="og:image:alt"]',
				"property",
				"og:image:alt",
				"Keshav Turbo Services — Industrial Turbine Engineering, Shamli, UP",
			);
			sm('meta[property="og:locale"]', "property", "og:locale", "en_IN");
			// og:locale:alternate — signals multilingual support to social crawlers
			sm(
				'meta[property="og:locale:alternate"]',
				"property",
				"og:locale:alternate",
				"hi_IN",
			);
			sm(
				'meta[property="og:site_name"]',
				"property",
				"og:site_name",
				BRAND_NAME,
			);
			if (pageType === "article" && publishedTime) {
				sm(
					'meta[property="article:published_time"]',
					"property",
					"article:published_time",
					publishedTime,
				);
				sm(
					'meta[property="article:author"]',
					"property",
					"article:author",
					BRAND_AUTHOR,
				);
				sm(
					'meta[property="article:section"]',
					"property",
					"article:section",
					"Industrial Engineering",
				);
			}

			// ── Twitter Card ──
			sm(
				'meta[name="twitter:card"]',
				"name",
				"twitter:card",
				"summary_large_image",
			);
			sm('meta[name="twitter:site"]', "name", "twitter:site", "@ksengg007");
			sm(
				'meta[name="twitter:creator"]',
				"name",
				"twitter:creator",
				"@ksengg007",
			);
			sm('meta[name="twitter:title"]', "name", "twitter:title", fullTitle);
			sm(
				'meta[name="twitter:description"]',
				"name",
				"twitter:description",
				fullDesc,
			);
			sm('meta[name="twitter:image"]', "name", "twitter:image", OG_IMAGE);
			sm(
				'meta[name="twitter:image:alt"]',
				"name",
				"twitter:image:alt",
				"Keshav Turbo Services — Industrial Turbine Engineering",
			);

			// ── Geo ──
			sm('meta[name="geo.region"]', "name", "geo.region", "IN-UP");
			sm(
				'meta[name="geo.placename"]',
				"name",
				"geo.placename",
				"Shamli, Uttar Pradesh",
			);
			sm(
				'meta[name="geo.position"]',
				"name",
				"geo.position",
				"29.4476;77.3003",
			);
			sm('meta[name="ICBM"]', "name", "ICBM", "29.4476, 77.3003");

			// ── JSON-LD ──
			if (schema) {
				let ld = document.getElementById("ld-json");
				if (!ld) {
					ld = document.createElement("script");
					ld.id = "ld-json";
					ld.type = "application/ld+json";
					document.head.appendChild(ld);
				}
				ld.textContent = JSON.stringify(schema);
			}
		}, [
			title,
			description,
			schema,
			pageType,
			canonicalPath,
			publishedTime,
			noIndex,
		]);
		return null;
	},
);
SEOHead.displayName = "SEOHead";

