// LANGUAGES alias used by the active-lang lookup elsewhere
const LANGUAGES = ALL_LANGUAGES;

// Cookie helpers (avoids direct document.cookie access per lint rules)
const getCookie = (name) => {
	const match = document.cookie.match(
		new RegExp(
			`(?:^|; )${name.replace(/([.$?*|{}()[\]/+^])/g, "\\$1")}=([^;]*)`,
		),
	);
	return match ? decodeURIComponent(match[1]) : undefined;
};
const setCookie = (name, value, attrs = {}) => {
	let str = `${encodeURIComponent(name)}=${encodeURIComponent(value)}`;
	if (attrs.path) str += `; path=${attrs.path}`;
	if (attrs.domain) str += `; domain=${attrs.domain}`;
	str += "; SameSite=Lax";
	// biome-ignore lint/suspicious/noDocumentCookie: direct assignment required for cookie write
	document.cookie = str;
};

const LanguageSwitcher = memo(({ scrolled }) => {
	const [isOpen, setIsOpen] = useState(false);
	const [langSearch, setLangSearch] = useState("");
	const [currentLang, setCurrentLang] = useState(() => {
		const langVal = getCookie("googtrans");
		if (langVal) {
			const langMatch = langVal.match(/^\/en\/(.+)$/);
			if (langMatch) return langMatch[1];
		}
		return "en";
	});
	const ref = useRef(null);
	const searchRef = useRef(null);

	useEffect(() => {
		const handleClickOutside = (event) => {
			if (ref.current && !ref.current.contains(event.target)) {
				setIsOpen(false);
				setLangSearch("");
			}
		};
		const handleKeyDown = (event) => {
			if (event.key === "Escape") {
				setIsOpen(false);
				setLangSearch("");
			}
		};
		document.addEventListener("mousedown", handleClickOutside);
		document.addEventListener("keydown", handleKeyDown);
		return () => {
			document.removeEventListener("mousedown", handleClickOutside);
			document.removeEventListener("keydown", handleKeyDown);
		};
	}, []);

	useEffect(() => {
		let timer;
		if (isOpen) {
			timer = setTimeout(() => searchRef.current?.focus(), 50);
		} else {
			// Defer the reset so we don't call setState synchronously inside an effect
			// (react-hooks/set-state-in-effect). A zero-delay timeout keeps the UX
			// identical — the search box clears after the dropdown closes.
			timer = setTimeout(() => setLangSearch(""), 0);
		}
		return () => clearTimeout(timer);
	}, [isOpen]);

	const changeLanguage = (langCode) => {
		setCurrentLang(langCode);
		setIsOpen(false);
		setLangSearch("");
		setCookie("googtrans", `/en/${langCode}`, {
			path: "/",
			domain: window.location.hostname,
		});
		setCookie("googtrans", `/en/${langCode}`, { path: "/" }); // for localhost and IP addresses
		window.location.reload();
	};

	const activeLang =
		LANGUAGES.find((l) => l.code === currentLang) || LANGUAGES[0];

	const isSearching = langSearch.trim().length > 0;
	const filteredLangs = isSearching
		? ALL_LANGUAGES.filter(
				(l) =>
					l.name.toLowerCase().includes(langSearch.toLowerCase()) ||
					l.code.toLowerCase().includes(langSearch.toLowerCase()),
			)
		: TOP_LANGUAGES;

	return (
		<div className="relative" ref={ref}>
			<button
				type="button"
				onClick={() => setIsOpen(!isOpen)}
				aria-label="Change Language"
				aria-haspopup="listbox"
				aria-expanded={isOpen}
				className={`flex items-center gap-2 px-3.5 py-2.5 rounded-xl font-bold text-[13px] transition-all duration-200 focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 ${
					scrolled
						? "bg-slate-100 border border-slate-200 text-slate-700 hover:bg-blue-50 hover:border-blue-300 hover:text-blue-700"
						: "bg-white/10 border border-white/25 text-white hover:bg-white/20 backdrop-blur-md"
				}`}
			>
				<FLAG_IMG flagCode={activeLang.flagCode} size={22} />
				<span
					className="text-[12px] font-black tracking-widest leading-none"
					style={{ color: scrolled ? activeLang.color : "#ffffff" }}
				>
					{activeLang.code === "zh-CN" ? "ZH" : activeLang.code.toUpperCase()}
				</span>
				<svg
					aria-hidden="true"
					className={`w-3.5 h-3.5 opacity-70 transition-transform duration-200 ${isOpen ? "rotate-180" : ""}`}
					fill="none"
					stroke="currentColor"
					viewBox="0 0 24 24"
				>
					<path
						strokeLinecap="round"
						strokeLinejoin="round"
						strokeWidth={2.5}
						d="M19 9l-7 7-7-7"
					/>
				</svg>
			</button>
			{isOpen && (
				<div className="absolute right-0 mt-2 w-64 bg-white rounded-xl shadow-2xl border border-slate-100 overflow-hidden z-250">
					{/* Search box */}
					<div className="px-3 pt-3 pb-2 border-b border-slate-100">
						<div className="flex items-center gap-2 bg-slate-50 border border-slate-200 rounded-lg px-2.5 py-1.5">
							<Search
								className="w-3.5 h-3.5 text-slate-400 shrink-0"
								aria-hidden="true"
							/>
							<input
								ref={searchRef}
								type="text"
								value={langSearch}
								onChange={(e) => setLangSearch(e.target.value)}
								placeholder="Search language…"
								className="flex-1 bg-transparent text-[12px] text-slate-700 placeholder-slate-400 outline-none"
								aria-label="Search languages"
							/>
							{langSearch && (
								<button
									type="button"
									onClick={() => setLangSearch("")}
									className="text-slate-400 hover:text-slate-600"
									aria-label="Clear search"
								>
									<X className="w-3 h-3" />
								</button>
							)}
						</div>
					</div>
					{/* Label row */}
					<div className="px-3.5 pt-2 pb-1 flex items-center justify-between">
						<span className="text-[10px] font-semibold text-slate-400 uppercase tracking-wider">
							{isSearching
								? `${filteredLangs.length} result${filteredLangs.length !== 1 ? "s" : ""}`
								: "Popular"}
						</span>
						{!isSearching && (
							<span className="text-[10px] text-slate-400">
								{ALL_LANGUAGES.length} total · search to see all
							</span>
						)}
					</div>
					<div
						role="listbox"
						aria-label="Select language"
						className="max-h-64 overflow-y-auto py-1 scrollbar-hide"
					>
						{filteredLangs.length === 0 && (
							<p className="text-center text-[12px] text-slate-400 py-4">
								No languages found
							</p>
						)}
						{filteredLangs.map((lang) => (
							<button
								type="button"
								key={lang.code}
								role="option"
								aria-selected={currentLang === lang.code}
								onClick={() => changeLanguage(lang.code)}
								className={`w-full text-left px-3.5 py-2 flex items-center gap-3 transition-colors hover:bg-slate-50 focus:outline-none focus:bg-slate-50 ${currentLang === lang.code ? "bg-slate-50" : ""}`}
								style={
									currentLang === lang.code
										? {
												borderLeft: `3px solid ${lang.color}`,
												paddingLeft: "10px",
											}
										: { borderLeft: "3px solid transparent" }
								}
							>
								{/* Flag */}
								<FLAG_IMG flagCode={lang.flagCode} size={28} />

								{/* Name + code stacked */}
								<div className="flex flex-col leading-none gap-0.75 min-w-0">
									<span
										className="text-[13px] font-bold truncate"
										style={{ color: lang.color }}
									>
										{lang.name}
									</span>
									<span className="text-[10px] font-medium text-slate-400 uppercase tracking-wider">
										{lang.code.toUpperCase()}
									</span>
								</div>

								{/* Active tick */}
								{currentLang === lang.code && (
									<CheckCircle2
										className="w-4 h-4 ml-auto shrink-0"
										style={{ color: lang.color }}
										aria-hidden="true"
									/>
								)}
							</button>
						))}
					</div>
				</div>
			)}
		</div>
	);
});
LanguageSwitcher.displayName = "LanguageSwitcher";

// ─── STATIC NAVBAR KEYFRAMES ─────────────────────────────────
// Defined once at module level — never re-injected on re-render.
// Fix C+D: removes the <style> tags that were injected inside conditional
// render blocks (mobile drawer and search popover) causing duplicated
// @keyframe declarations on every open/close cycle.
const NAVBAR_STYLES = `
@keyframes mobileDrawerIn {
  from { opacity: 0; transform: translateY(-8px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes searchPopoverIn {
  from { opacity: 0; transform: translateY(-6px) scale(0.98); }
  to   { opacity: 1; transform: translateY(0)   scale(1); }
}
`;
let _navbarStylesInjected = false;
function injectNavbarStyles() {
	if (_navbarStylesInjected || typeof document === "undefined") return;
	const el = document.createElement("style");
	el.dataset.id = "ke-navbar-keyframes";
	el.textContent = NAVBAR_STYLES;
	document.head.appendChild(el);
	_navbarStylesInjected = true;
}
injectNavbarStyles(); // runs once at module evaluation time

// ─── MORE DROPDOWN ──────────────────────────────────────────────
// Fix 3: Houses nav links that overflow at the lg breakpoint (Blog, etc.)
// Uses same click-outside + Escape key pattern as LanguageSwitcher.
const MoreDropdown = memo(({ links, scrolled, isActive, handleNav }) => {
	const [open, setOpen] = useState(false);
	const ref = useRef(null);

	useEffect(() => {
		const handleClickOutside = (e) => {
			if (ref.current && !ref.current.contains(e.target)) setOpen(false);
		};
		const handleKey = (e) => {
			if (e.key === "Escape") setOpen(false);
		};
		document.addEventListener("mousedown", handleClickOutside);
		document.addEventListener("keydown", handleKey);
		return () => {
			document.removeEventListener("mousedown", handleClickOutside);
			document.removeEventListener("keydown", handleKey);
		};
	}, []);

	const anyActive = links.some((l) => isActive(l.path));

	return (
		<div className="relative" ref={ref}>
			<button
				type="button"
				onClick={() => setOpen((p) => !p)}
				aria-haspopup="menu"
				aria-expanded={open}
				className={`relative flex items-center gap-1 px-2 py-1.5 text-[11.5px] xl:text-[12.5px] font-bold uppercase tracking-wider transition-all duration-200 rounded-md focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 group whitespace-nowrap
				${
					anyActive
						? scrolled
							? "text-blue-600"
							: "text-white"
						: scrolled
							? "text-slate-600 hover:text-slate-900"
							: "text-slate-300 hover:text-white"
				}`}
			>
				More
				<svg
					aria-hidden="true"
					className={`w-3 h-3 opacity-70 transition-transform duration-200 ${open ? "rotate-180" : ""}`}
					fill="none"
					stroke="currentColor"
					viewBox="0 0 24 24"
				>
					<path
						strokeLinecap="round"
						strokeLinejoin="round"
						strokeWidth={2.5}
						d="M19 9l-7 7-7-7"
					/>
				</svg>
				{/* Underline indicator */}
				<span
					className={`absolute bottom-0 left-0 right-0 h-0.5 rounded-full origin-center transition-transform duration-300
					${anyActive ? "scale-x-75 bg-blue-500" : "scale-x-0 group-hover:scale-x-50 bg-blue-400/60"}`}
					aria-hidden="true"
				/>
			</button>

			{open && (
				<div
					role="menu"
					aria-label="More navigation links"
					className="absolute top-[calc(100%+10px)] left-0 min-w-40 bg-white rounded-xl shadow-2xl border border-slate-100 overflow-hidden z-200"
					style={{
						animation: "searchPopoverIn 0.15s cubic-bezier(0.3,0,0,1) both",
					}}
				>
					{links.map((link) => (
						<a
							key={link.name}
							href={`#${link.path}`}
							role="menuitem"
							onClick={(e) => {
								e.preventDefault();
								handleNav(link.path);
								setOpen(false);
							}}
							aria-current={isActive(link.path) ? "page" : undefined}
							className={`flex items-center justify-between px-4 py-2.5 text-sm font-bold transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-500
							${
								isActive(link.path)
									? "text-blue-600 bg-blue-50"
									: "text-slate-700 hover:text-blue-600 hover:bg-slate-50"
							}`}
						>
							{link.name}
							{isActive(link.path) && (
								<span
									className="w-1.5 h-1.5 rounded-full bg-blue-500 shrink-0 ml-3"
									aria-hidden="true"
								/>
							)}
						</a>
					))}
				</div>
			)}
		</div>
	);
});
MoreDropdown.displayName = "MoreDropdown";

// ─── NAV DROPDOWN — hover/tap mega-menu for Products & Services ───────────────
// Fix 6 (audit): reduces clicks to any category from 2+ to 1.
