const NavDropdown = memo(
	({ label, items, basePath, scrolled, isActive, navigate, onClose }) => {
		const [open, setOpen] = useState(false);
		const ref = useRef(null);
		const timerRef = useRef(null);

		useEffect(() => {
			const handleKey = (e) => {
				if (e.key === "Escape") setOpen(false);
			};
			document.addEventListener("keydown", handleKey);
			return () => {
				document.removeEventListener("keydown", handleKey);
				clearTimeout(timerRef.current);
			};
		}, []);

		const handleMouseEnter = useCallback(() => {
			clearTimeout(timerRef.current);
			setOpen(true);
		}, []);
		const handleMouseLeave = useCallback(() => {
			timerRef.current = setTimeout(() => setOpen(false), 120);
		}, []);

		const handleItemClick = useCallback(
			(item) => {
				setOpen(false);
				onClose?.();
				if (item.cat) {
					// Product category — navigate then dispatch immediately; ProductsPage
					// listens for this event and the slight React render delay is enough
					navigate(basePath);
					requestAnimationFrame(() => {
						window.dispatchEvent(
							new CustomEvent("ke:setProductCategory", { detail: item.cat }),
						);
					});
				} else if (item.id) {
					// Industry or Service with a direct detail page
					navigate(`${basePath}/${item.id}`);
				} else {
					navigate(basePath);
				}
			},
			[navigate, basePath, onClose],
		);

		const active = isActive(basePath);

		return (
			<nav
				className="relative"
				ref={ref}
				aria-label={label}
				onMouseEnter={handleMouseEnter}
				onMouseLeave={handleMouseLeave}
			>
				<button
					type="button"
					onClick={() => {
						navigate(basePath);
						onClose?.();
					}}
					onKeyDown={(e) => {
						if (e.key === "Enter" || e.key === " ") {
							e.preventDefault();
							setOpen((p) => !p);
						}
					}}
					aria-haspopup="menu"
					aria-expanded={open}
					className={`relative flex items-center gap-0.5 px-2 py-1.5 text-[11.5px] xl:text-[12.5px] font-bold uppercase tracking-wider transition-all duration-200 rounded-md focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 group whitespace-nowrap
				${
					active
						? scrolled
							? "text-blue-600"
							: "text-white"
						: scrolled
							? "text-slate-600 hover:text-slate-900"
							: "text-slate-300 hover:text-white"
				}`}
				>
					{label}
					<svg
						aria-hidden="true"
						className={`w-3 h-3 opacity-60 transition-transform duration-200 ${open ? "rotate-180" : ""}`}
						fill="none"
						stroke="currentColor"
						viewBox="0 0 24 24"
					>
						<path
							strokeLinecap="round"
							strokeLinejoin="round"
							strokeWidth={2.5}
							d="M19 9l-7 7-7-7"
						/>
					</svg>
					<span
						className={`absolute bottom-0 left-0 right-0 h-0.5 rounded-full origin-center transition-transform duration-300 ${active ? "scale-x-75 bg-blue-500" : "scale-x-0 group-hover:scale-x-50 bg-blue-400/60"}`}
						aria-hidden="true"
					/>
				</button>

				{open && (
					<div
						role="menu"
						aria-label={`${label} menu`}
						className={`absolute top-[calc(100%+10px)] left-0 bg-white rounded-xl shadow-2xl border border-slate-100 overflow-hidden z-200 py-1 ${label === "Industries" ? "min-w-[16rem]" : "min-w-55"}`}
						style={{
							animation: "searchPopoverIn 0.15s cubic-bezier(0.3,0,0,1) both",
						}}
						onMouseEnter={handleMouseEnter}
						onMouseLeave={handleMouseLeave}
					>
						{items.map((item) => (
							<button
								key={item.label}
								type="button"
								role="menuitem"
								onClick={() => handleItemClick(item)}
								className="w-full text-left flex items-center gap-3 px-4 py-2.5 text-sm font-semibold text-slate-700 hover:text-blue-600 hover:bg-blue-50 transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-blue-500 group/item"
							>
								<span
									className="w-1.5 h-1.5 rounded-full bg-blue-400 group-hover/item:bg-blue-600 shrink-0 transition-colors"
									aria-hidden="true"
								/>
								{item.label}
								{item.id && (
									<svg className="w-3 h-3 ml-auto text-slate-300 group-hover/item:text-blue-400 transition-colors shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true">
										<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 5l7 7-7 7" />
									</svg>
								)}
							</button>
						))}
						<div className="border-t border-slate-100 mt-1 pt-1">
							<button
								type="button"
								role="menuitem"
								onClick={() => {
									navigate(basePath);
									setOpen(false);
									onClose?.();
								}}
								className="w-full text-left px-4 py-2 text-xs font-black text-blue-600 hover:bg-blue-50 transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-blue-500 uppercase tracking-wider flex items-center gap-1"
							>
								View all {label}
								<svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true">
									<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 5l7 7-7 7" />
								</svg>
							</button>
						</div>
					</div>
				)}
			</nav>
		);
	},
);
NavDropdown.displayName = "NavDropdown";

// ─── NAVBAR ───────────────────────────────────────────────────
const Navbar = memo(({ currentPath, navigate }) => {
	const [isOpen, setIsOpen] = useState(false);
	const [isSearchOpen, setIsSearchOpen] = useState(false);
	const [query, setQuery] = useState("");
	const [scrolled, setScrolled] = useState(false);
	const [isVisible, setIsVisible] = useState(true);
	// Mobile expandable sub-menus for Services / Products
	const [mobileExpanded, setMobileExpanded] = useState(null);
	const fmtPrice = useFmtPrice();
	const menuRef = useRef(null);
	const searchInputRef = useRef(null);
	// PERF: ref mirrors query so outside-click handler reads current value without
	// needing query in its dependency array (which would re-register on every keystroke)
	const queryRef = useRef("");
	// PERF: mirror isOpen/isSearchOpen in refs so scroll handler reads current values
	// without needing them in its deps array (which caused listener re-registration on every toggle)
	const isOpenRef = useRef(false);
	const isSearchOpenRef = useRef(false);

	useEffect(() => {
		isOpenRef.current = isOpen;
	}, [isOpen]);
	useEffect(() => {
		isSearchOpenRef.current = isSearchOpen;
	}, [isSearchOpen]);

	useEffect(() => {
		let scrollTimeout;

		let lastScrollY = window.scrollY;

		const handleScroll = () => {
			const currentScrollY = window.scrollY;
			const scrollingDown = currentScrollY > lastScrollY;
			lastScrollY = currentScrollY;

			setScrolled(currentScrollY > 20);

			// Always show when near top, menu open, or search open
			if (
				currentScrollY < 100 ||
				isOpenRef.current ||
				isSearchOpenRef.current
			) {
				setIsVisible(true);
			} else if (scrollingDown) {
				// Hide only when scrolling DOWN
				setIsVisible(false);
			} else {
				// Scrolling UP — always show immediately
				setIsVisible(true);
			}

			// Belt-and-suspenders: ensure visible after scroll settles
			clearTimeout(scrollTimeout);
			scrollTimeout = setTimeout(() => {
				setIsVisible(true);
			}, 350);
		};

		window.addEventListener("scroll", handleScroll, { passive: true });
		return () => {
			window.removeEventListener("scroll", handleScroll);
			clearTimeout(scrollTimeout);
		};
	}, []);

	// Auto-focus desktop search input when popover opens
	useEffect(() => {
		if (isSearchOpen && window.innerWidth >= 1024) {
			// Small delay lets the popover mount fully before focusing
			const t = setTimeout(() => searchInputRef.current?.focus(), 50);
			return () => clearTimeout(t);
		}
	}, [isSearchOpen]);

	// AUDIT FIX: Body scroll lock when mobile menu/search is open
	useEffect(() => {
		if (typeof document === "undefined") return;
		if ((isOpen || isSearchOpen) && window.innerWidth < 1024) {
			document.body.style.overflow = "hidden";
		} else {
			document.body.style.overflow = "";
		}
		return () => {
			document.body.style.overflow = "";
		};
	}, [isOpen, isSearchOpen]);

	const q = query.toLowerCase().trim();
	// keep ref in sync for the event handler
	useEffect(() => {
		queryRef.current = query;
	}, [query]);
	// Defer search computation so keystrokes feel instant even on slow devices
	const deferredQ = React.useDeferredValue(q);
	const searchResults = useMemo(() => {
		if (!deferredQ) return [];
		return [
			...SERVICES.filter(
				(s) =>
					s.title?.toLowerCase().includes(deferredQ) ||
					s.desc?.toLowerCase().includes(deferredQ),
			).map((s) => ({
				id: s.id,
				title: s.title,
				desc: s.desc,
				type: "Service",
				path: `/service/${s.id}`,
				image: s.image,
				priceRange: null,
			})),
			...PRODUCTS.filter(
				(p) =>
					p.title?.toLowerCase().includes(deferredQ) ||
					p.desc?.toLowerCase().includes(deferredQ) ||
					p.category?.toLowerCase().includes(deferredQ) ||
					p.features?.some((f) => f.toLowerCase().includes(deferredQ)),
			).map((p) => ({
				id: p.id,
				title: p.title,
				desc: p.desc,
				type: "Product",
				category: p.category,
				path: `/product/${p.id}`,
				image: p.images?.[0],
				priceRange: p.priceRange || null,
			})),
		].slice(0, 8);
	}, [deferredQ]);

	// PERF: combine outside-click and Escape into one effect with one pair of listeners
	useEffect(() => {
		const onMouse = (e) => {
			if (menuRef.current && !menuRef.current.contains(e.target)) {
				setIsOpen(false);
				setMobileExpanded(null);
				// read latest query via ref to avoid adding query to deps (would re-register on every keystroke)
				setIsSearchOpen((prev) => {
					if (!queryRef.current) return false;
					return prev;
				});
			}
		};
		const onKey = (e) => {
			if (e.key === "Escape") {
				setIsOpen(false);
				setMobileExpanded(null);
				setIsSearchOpen(false);
			}
		};
		document.addEventListener("mousedown", onMouse);
		document.addEventListener("keydown", onKey);
		return () => {
			document.removeEventListener("mousedown", onMouse);
			document.removeEventListener("keydown", onKey);
		};
	}, []);
	const isActive = useCallback(
		(path) => {
			if (path === "/" && currentPath !== "/") return false;
			// Detail pages use a singular prefix (/product/, /service/, /industry/, /blog/, /project/)
			// while nav links point to the plural index (/products, /services, /industries, /blog, /projects).
			if (currentPath.startsWith("/product/") && path === "/products")
				return true;
			if (currentPath.startsWith("/service/") && path === "/services")
				return true;
			if (currentPath.startsWith("/industry/") && path === "/industries")
				return true;
			if (currentPath.startsWith("/blog/") && path === "/blog") return true;
			if (currentPath.startsWith("/project/") && path === "/projects")
				return true;
			return currentPath === path;
		},
		[currentPath],
	);
	const handleNav = useCallback(
		(path) => {
			navigate(path);
			setIsOpen(false);
			setIsSearchOpen(false);
			setQuery("");
			setMobileExpanded(null);
		},
		[navigate],
	);
	return (
		<nav
			ref={menuRef}
			aria-label="Main navigation"
			className={`fixed top-0 left-0 w-full z-50 transition-all duration-500 ease-[cubic-bezier(0.3,0,0,1)] border-b ${isVisible ? "translate-y-0" : "-translate-y-full"} ${scrolled ? "bg-white/97 backdrop-blur-xl border-slate-200 shadow-lg" : "bg-[#0A192F]/95 backdrop-blur-sm border-white/10"}`}
		>
			<a
				href="#main-content"
				className="sr-only focus:not-sr-only focus:absolute focus:top-4 focus:left-4 bg-blue-600 text-white px-4 py-2 rounded z-100 font-bold"
			>
				Skip to main content
			</a>
			{/* ── INNER ROW: fixed height 64px so scroll-state transition never jitters ── */}
			<div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
				<div className="flex justify-between items-center h-16">
					<BrandLogo scrolled={scrolled} navigate={navigate} />
					{/*
					 * ── DESKTOP RIGHT SECTION ────────────────────────────────────────────
					 * Fix 3 – Nav-link count: 6 primary links + "More ▾" dropdown for Blog.
					 *          Prevents crowding at lg (1024px) breakpoint.
					 * Fix 5 – LanguageSwitcher now lives AFTER nav links, before search
					 *          (correct semantic order: nav | utility | action).
					 * Fix 4 – Search is now an icon-only toggle that opens a position:absolute
					 *          popover — zero layout shift on expand.
					 * Fix 7 – Removed py-2/py-3 from <nav>; row height locked to h-16 (64px)
					 *          so scroll-state colour transition never jitters bar height.
					 * ────────────────────────────────────────────────────────────────────
					 */}
					<div className="hidden lg:flex items-center gap-0.5 xl:gap-1">
						{/* Primary nav links (first 6) — Services & Products get hover dropdowns */}
						{NAV_LINKS.slice(0, 6).map((link) => {
							if (link.name === "Services") {
								return (
									<NavDropdown
										key="Services"
										label="Services"
										items={NAV_SERVICES_MENU}
										basePath="/services"
										scrolled={scrolled}
										isActive={isActive}
										navigate={handleNav}
									/>
								);
							}
							if (link.name === "Products") {
								return (
									<NavDropdown
										key="Products"
										label="Products"
										items={NAV_PRODUCTS_MENU}
										basePath="/products"
										scrolled={scrolled}
										isActive={isActive}
										navigate={handleNav}
									/>
								);
							}
							if (link.name === "Industries") {
								return (
									<NavDropdown
										key="Industries"
										label="Industries"
										items={NAV_INDUSTRIES_MENU}
										basePath="/industries"
										scrolled={scrolled}
										isActive={isActive}
										navigate={handleNav}
									/>
								);
							}
							return (
								<a
									key={link.name}
									href={`#${link.path}`}
									onClick={(e) => {
										e.preventDefault();
										handleNav(link.path);
									}}
									aria-current={isActive(link.path) ? "page" : undefined}
									className={`relative px-2 py-1.5 text-[11.5px] xl:text-[12.5px] font-bold uppercase tracking-wider transition-all duration-200 rounded-md focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 group whitespace-nowrap ${
										isActive(link.path)
											? scrolled
												? "text-blue-600"
												: "text-white"
											: scrolled
												? "text-slate-600 hover:text-slate-900"
												: "text-slate-300 hover:text-white"
									}`}
								>
									{link.name}
									<span
										className={`absolute bottom-0 left-0 right-0 h-0.5 rounded-full origin-center transition-transform duration-300 ${isActive(link.path) ? "scale-x-75 bg-blue-500" : "scale-x-0 group-hover:scale-x-50 bg-blue-400/60"}`}
										aria-hidden="true"
									/>
								</a>
							);
						})}

						{/* "More ▾" dropdown for overflow links (Blog) — Fix 3 + audit fix 10 */}
						{NAV_LINKS.length > 6 && (
							<MoreDropdown
								links={NAV_LINKS.slice(6)}
								scrolled={scrolled}
								isActive={isActive}
								handleNav={handleNav}
							/>
						)}

						{/* Divider */}
						<div
							className={`w-px h-5 mx-1.5 shrink-0 ${scrolled ? "bg-slate-200" : "bg-white/20"}`}
							aria-hidden="true"
						/>

						{/* Language switcher — Fix 5: now correctly after nav links */}
						<LanguageSwitcher scrolled={scrolled} />

						{/* Search icon toggle — Fix 4: popover pattern, no layout shift */}
						<search className="relative">
							<button
								type="button"
								onClick={() => {
									setIsSearchOpen((prev) => {
										if (prev) {
											setQuery("");
											return false;
										}
										return true;
									});
								}}
								aria-label={
									isSearchOpen ? "Close search" : "Search products and services"
								}
								aria-expanded={isSearchOpen}
								aria-controls="desktop-search-popover"
								className={`p-2 rounded-lg transition-all duration-200 active:scale-95 focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 ${
									isSearchOpen
										? scrolled
											? "bg-blue-600 text-white"
											: "bg-blue-500/80 text-white"
										: scrolled
											? "text-slate-600 hover:bg-slate-100"
											: "text-slate-300 hover:bg-white/10 hover:text-white"
								}`}
							>
								{isSearchOpen ? (
									<X className="w-4 h-4" aria-hidden="true" />
								) : (
									<Search className="w-4 h-4" aria-hidden="true" />
								)}
							</button>

							{/* Search popover — absolutely positioned, never shifts siblings */}
							{isSearchOpen && (
								// biome-ignore lint/a11y/useSemanticElements: search landmark on div is intentional; <search> not yet in JSX typedefs
								<div
									id="desktop-search-popover"
									role="search"
									className="absolute top-[calc(100%+14px)] right-0 w-120 max-w-[90vw] bg-white rounded-2xl shadow-2xl border border-slate-200 overflow-hidden z-200"
									style={{
										animation:
											"searchPopoverIn 0.18s cubic-bezier(0.3,0,0,1) both",
									}}
								>
									<div className="flex items-center gap-2 px-4 py-3 border-b border-slate-100">
										<Search
											className="w-4 h-4 text-slate-400 shrink-0"
											aria-hidden="true"
										/>
										<label htmlFor="nav-search-desktop" className="sr-only">
											Search products and services
										</label>
										<input
											id="nav-search-desktop"
											ref={searchInputRef}
											type="text"
											placeholder="Search products & services…"
											value={query}
											// biome-ignore lint/a11y/noAutofocus: intentional — user clicked search icon to open this field
											autoFocus
											onChange={(e) => setQuery(e.target.value)}
											className="flex-1 bg-transparent text-sm text-slate-900 placeholder:text-slate-400 outline-none"
										/>
										{query && (
											<button
												type="button"
												onClick={() => setQuery("")}
												aria-label="Clear search"
												className="text-slate-400 hover:text-slate-700 focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 rounded p-0.5"
											>
												<X className="w-3.5 h-3.5" aria-hidden="true" />
											</button>
										)}
									</div>
									<div className="max-h-[60vh] overflow-y-auto p-2">
										{!query ? (
											<p className="text-center text-xs text-slate-400 py-6">
												Start typing to search products &amp; services
											</p>
										) : searchResults.length === 0 ? (
											<div
												className="p-8 text-center"
												role="status"
												aria-live="polite"
											>
												<Search
													className="w-9 h-9 text-slate-300 mx-auto mb-3"
													aria-hidden="true"
												/>
												<p className="text-sm font-semibold text-slate-600 mb-1">
													No results for &ldquo;{query}&rdquo;
												</p>
												<p className="text-xs text-slate-400 leading-relaxed">
													Try:{" "}
													<span className="font-medium text-blue-600">
														Turbine Overhauling
													</span>
													,{" "}
													<span className="font-medium text-blue-600">
														Dynamic Balancing
													</span>
													,{" "}
													<span className="font-medium text-blue-600">
														Lube Oil
													</span>
												</p>
											</div>
										) : (
											<ul className="space-y-1" aria-label="Search results">
												{searchResults.map((r) => (
													<li key={r.id}>
														<button
															type="button"
															onClick={() => {
																setIsSearchOpen(false);
																setQuery("");
																navigate(r.path);
																setIsOpen(false);
															}}
															className="w-full text-left p-3 rounded-xl hover:bg-slate-50 transition-colors flex flex-col gap-1 focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-500"
														>
															<div className="flex gap-3 w-full items-center">
																<div className="w-12 h-12 shrink-0 rounded bg-slate-100 border border-slate-200/50 overflow-hidden flex items-center justify-center relative shadow-sm">
																	<div
																		className="w-6 h-6 [&>svg]:w-6 [&>svg]:h-6 [&>svg]:text-slate-300 [&>svg]:transition-none pointer-events-none"
																		aria-hidden="true"
																	>
																		{getCategoryIcon(r.category)}
																	</div>
																	{r.image && (
																		<img
																			src={r.image}
																			alt=""
																			className="absolute inset-0 w-full h-full object-cover mix-blend-multiply"
																			onError={(e) => {
																				e.target.style.display = "none";
																			}}
																		/>
																	)}
																</div>
																<div className="flex-1 min-w-0 flex flex-col justify-center">
																	<div className="flex justify-between items-start">
																		<span className="font-bold text-slate-900 text-sm line-clamp-2 pr-2">
																			{r.title}
																		</span>
																		<div className="flex items-center gap-1 shrink-0 ml-2 mt-0.5">
																			{r.type === "Product" && (
																				<span className="text-[9px] font-black uppercase tracking-widest px-1.5 py-0.5 rounded bg-slate-100 text-slate-600">
																					{r.category}
																				</span>
																			)}
																			<span
																				className={`text-[9px] font-black uppercase tracking-widest px-1.5 py-0.5 rounded ${r.type === "Product" ? "bg-blue-100 text-blue-700" : "bg-emerald-100 text-emerald-700"}`}
																			>
																				{r.type}
																			</span>
																		</div>
																	</div>
																	<span className="text-xs text-slate-500 line-clamp-1 mt-0.5">
																		{r.desc}
																	</span>
																	{r.priceRange && (
																		<span className="text-[10px] font-black text-blue-600 mt-0.5">
																			{fmtPrice(r.priceRange.min)}–
																			{fmtPrice(r.priceRange.max)}{" "}
																			{r.priceRange.unit}
																		</span>
																	)}
																</div>
															</div>
														</button>
													</li>
												))}
											</ul>
										)}
									</div>
								</div>
							)}
						</search>

						{/* Get Quote CTA */}
						<button
							type="button"
							onClick={() => handleNav("/contact")}
							className={`ml-1 px-4 py-2 rounded-lg font-bold text-[12.5px] tracking-wide whitespace-nowrap transition-all duration-200 shadow-md hover:shadow-lg hover:-translate-y-0.5 focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-300 flex items-center gap-1.5 ${scrolled ? "bg-blue-600 text-white hover:bg-blue-700" : "bg-blue-500 text-white hover:bg-blue-400 ring-1 ring-white/20"}`}
						>
							<PhoneCall className="w-3.5 h-3.5" aria-hidden="true" />
							Get Quote
						</button>
					</div>

					{/*
					 * ── MOBILE CONTROLS ─────────────────────────────────────────────────
					 * Fix 5 – Added "Call Us" compact pill on sm+ screens to fill the wide
					 *          dead zone between logo and icon cluster on wider phones.
					 * ──────────────────────────────────────────────────────────────────
					 */}
					<div className="lg:hidden flex items-center gap-1.5">
						{/* Compact "Call Us" pill — fills dead zone on wider phones */}
						<a
							href={`tel:${CONTACT_INFO.phones[0].replace(/\s/g, "")}`}
							aria-label={`Call us: ${CONTACT_INFO.phones[0]}`}
							className={`hidden sm:flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-[11px] font-black tracking-wide transition-all duration-200 border mr-1 ${
								scrolled
									? "bg-blue-50 border-blue-200 text-blue-700 hover:bg-blue-600 hover:text-white hover:border-blue-600"
									: "bg-white/10 border-white/20 text-white hover:bg-white/20 backdrop-blur-sm"
							}`}
						>
							<Phone className="w-3.5 h-3.5 shrink-0" aria-hidden="true" />
							<span>Call Us</span>
						</a>
						<LanguageSwitcher scrolled={scrolled} />
						<button
							type="button"
							onClick={() => {
								if (isSearchOpen) {
									setIsSearchOpen(false);
									setQuery("");
								} else {
									// Open unified drawer with search focused
									setIsSearchOpen(true);
									setIsOpen(true);
								}
							}}
							aria-label={isSearchOpen ? "Close search" : "Open search"}
							aria-expanded={isSearchOpen}
							aria-controls="mobile-nav"
							className={`p-2.5 rounded-lg transition-all duration-200 active:scale-95 focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 ${scrolled ? "bg-slate-100 text-slate-600 hover:bg-blue-600 hover:text-white" : "bg-white/10 text-white hover:bg-white/20 backdrop-blur-sm"}`}
						>
							<Search className="h-5 w-5" aria-hidden="true" />
						</button>
						<button
							type="button"
							onClick={() => {
								const next = !isOpen;
								setIsOpen(next);
								if (!next) {
									setIsSearchOpen(false);
									setQuery("");
									setMobileExpanded(null);
								}
							}}
							aria-label={
								isOpen ? "Close navigation menu" : "Open navigation menu"
							}
							aria-expanded={isOpen}
							aria-controls="mobile-nav"
							className={`p-2.5 rounded-lg transition-all duration-200 active:scale-95 focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 ${scrolled ? "bg-slate-100 text-slate-700 hover:bg-slate-200" : "bg-white/10 text-white hover:bg-white/20 backdrop-blur-sm"}`}
						>
							{isOpen ? (
								<X className="h-5 w-5" aria-hidden="true" />
							) : (
								<Menu className="h-5 w-5" aria-hidden="true" />
							)}
						</button>
					</div>
				</div>
			</div>
			{/* Mobile drawer — unified: search + nav in one panel (Fix 8) */}
			{(isOpen || isSearchOpen) && (
				<div
					id="mobile-nav"
					className="lg:hidden absolute top-full left-0 w-full bg-white shadow-2xl border-t border-slate-100 max-h-[85vh] overflow-y-auto"
					role="menu"
					style={{
						animation: "mobileDrawerIn 0.25s cubic-bezier(0.3,0,0,1) both",
						paddingBottom: "env(safe-area-inset-bottom, 0px)",
					}}
				>
					{/*
					 * Fix 8 — Unified mobile drawer:
					 * Search field is always shown at the top of the drawer (regardless of
					 * whether the user tapped the 🔍 or ☰ button), with nav links below.
					 * This eliminates the confusing "search-only vs nav-only" visual split.
					 */}

					{/* ── Search always at the top of the unified drawer ── */}
					<div className="px-4 pt-4 pb-3 border-b border-slate-100">
						<div className="relative">
							<Search
								className="w-4 h-4 absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-400"
								aria-hidden="true"
							/>
							<label htmlFor="mobile-drawer-search" className="sr-only">
								Search products and services
							</label>
							<input
								id="mobile-drawer-search"
								type="text"
								placeholder="Search products & services…"
								value={query}
								onChange={(e) => setQuery(e.target.value)}
								className="w-full bg-slate-100 border-none rounded-xl py-3 pl-10 pr-10 focus:ring-2 focus:ring-blue-500 text-slate-900 placeholder:text-slate-500 text-sm outline-none"
							/>
							{query && (
								<button
									type="button"
									onClick={() => setQuery("")}
									aria-label="Clear search"
									className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-700"
								>
									<X className="w-4 h-4" aria-hidden="true" />
								</button>
							)}
						</div>
						{query && (
							<div className="max-h-[45vh] overflow-y-auto mt-2 bg-white rounded-xl border border-slate-100 shadow-inner">
								{searchResults.length === 0 ? (
									<div
										className="p-6 text-center"
										role="status"
										aria-live="polite"
									>
										<Search
											className="w-8 h-8 text-slate-300 mx-auto mb-2"
											aria-hidden="true"
										/>
										<p className="text-sm font-semibold text-slate-600 mb-1">
											No results for &ldquo;{query}&rdquo;
										</p>
										<p className="text-xs text-slate-400">
											Try: Turbine Overhauling, Dynamic Balancing, Lube Oil
										</p>
									</div>
								) : (
									<ul className="divide-y divide-slate-100">
										{searchResults.map((r) => (
											<li key={r.id}>
												<button
													type="button"
													onClick={() => {
														setIsSearchOpen(false);
														setQuery("");
														navigate(r.path);
														setIsOpen(false);
													}}
													className="w-full text-left p-3 hover:bg-slate-50 transition-colors flex gap-3 items-center focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-500"
												>
													<div className="w-10 h-10 shrink-0 rounded-lg bg-slate-100 border border-slate-200/50 overflow-hidden flex items-center justify-center relative">
														<div
															className="w-5 h-5 [&>svg]:w-5 [&>svg]:h-5 [&>svg]:text-slate-300 [&>svg]:transition-none pointer-events-none"
															aria-hidden="true"
														>
															{getCategoryIcon(r.category)}
														</div>
														{r.image && (
															<img
																src={r.image}
																alt=""
																className="absolute inset-0 w-full h-full object-cover mix-blend-multiply"
																onError={(e) => {
																	e.target.style.display = "none";
																}}
															/>
														)}
													</div>
													<div className="flex-1 min-w-0">
														<span className="font-bold text-slate-900 text-sm line-clamp-1 block">
															{r.title}
														</span>
														<span
															className={`text-[10px] font-black uppercase tracking-widest px-1.5 py-0.5 rounded ${r.type === "Product" ? "bg-blue-100 text-blue-700" : "bg-emerald-100 text-emerald-700"}`}
														>
															{r.type}
														</span>
														{r.priceRange && (
															<span className="block text-[10px] font-black text-blue-600 mt-0.5">
																{fmtPrice(r.priceRange.min)}–
																{fmtPrice(r.priceRange.max)}
															</span>
														)}
													</div>
												</button>
											</li>
										))}
									</ul>
								)}
							</div>
						)}
					</div>

					{/* ── Nav links — shown when drawer is open with no active search query ── */}
					{(isOpen || isSearchOpen) && !query && (
						<div className="px-4 py-5">
							<ul className="space-y-1 mb-5">
								{NAV_LINKS.map((link) => {
									// Services, Products and Industries get an expand/collapse sub-menu
									const subItems =
										link.name === "Services"
											? NAV_SERVICES_MENU
											: link.name === "Products"
												? NAV_PRODUCTS_MENU
												: link.name === "Industries"
													? NAV_INDUSTRIES_MENU
													: null;
									const expanded = mobileExpanded === link.name;
									const active = isActive(link.path);

									return (
										<li key={link.name}>
											{subItems ? (
												/* ── Split row: label navigates, chevron toggles sub-menu ── */
												<div
													className={`flex items-center rounded-xl overflow-hidden border transition-all ${
														active
															? "border-blue-200 bg-blue-50"
															: expanded
																? "border-slate-200 bg-slate-50"
																: "border-transparent"
													}`}
												>
													{/* Label — navigates to the section page */}
													<button
														type="button"
														onClick={() => handleNav(link.path)}
														aria-current={active ? "page" : undefined}
														className={`flex-1 text-left px-4 py-3.5 text-base font-bold tracking-tight transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-blue-500 ${
															active ? "text-blue-600" : "text-slate-700"
														}`}
													>
														{link.name}
													</button>
													{/* Chevron — only toggles sub-menu */}
													<button
														type="button"
														onClick={() => setMobileExpanded(expanded ? null : link.name)}
														aria-expanded={expanded}
														aria-label={`${expanded ? "Collapse" : "Expand"} ${link.name} menu`}
														className={`px-4 py-3.5 transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-blue-500 border-l ${
															expanded
																? "border-blue-200 text-blue-500"
																: "border-slate-200 text-slate-400"
														}`}
													>
														<svg
															aria-hidden="true"
															className={`w-4 h-4 transition-transform duration-200 ${expanded ? "rotate-180 text-blue-500" : ""}`}
															fill="none"
															stroke="currentColor"
															viewBox="0 0 24 24"
														>
															<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 9l-7 7-7-7" />
														</svg>
													</button>
												</div>
											) : (
												/* ── Plain nav item — just navigates ── */
												<button
													type="button"
													onClick={() => handleNav(link.path)}
													aria-current={active ? "page" : undefined}
													className={`w-full text-left flex items-center justify-between px-4 py-3.5 rounded-xl text-base font-bold tracking-tight transition-all focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 ${
														active
															? "text-blue-600 bg-blue-50 border border-blue-200"
															: "text-slate-700 hover:text-blue-600 hover:bg-slate-50 border border-transparent"
													}`}
												>
													{link.name}
													{active && (
														<span className="w-1.5 h-1.5 rounded-full bg-blue-500 shrink-0" aria-hidden="true" />
													)}
												</button>
											)}

											{/* ── Expandable sub-items ── */}
											{subItems && expanded && (
												<ul className="ml-2 mt-1 mb-1 space-y-0.5 border-l-2 border-blue-100 pl-3">
													{subItems.map((item) => (
														<li key={item.label}>
															<button
																type="button"
																onClick={() => {
																	setMobileExpanded(null);
																	if (item.id && link.name === "Industries") {
																		handleNav(`/industry/${item.id}`);
																	} else if (item.id && link.name === "Services") {
																		handleNav(`/service/${item.id}`);
																	} else if (item.cat) {
																		handleNav(link.path);
																		requestAnimationFrame(() => {
																			window.dispatchEvent(
																				new CustomEvent("ke:setProductCategory", { detail: item.cat }),
																			);
																		});
																	} else {
																		handleNav(link.path);
																	}
																}}
																className="w-full text-left px-3 py-2.5 text-sm font-semibold text-slate-600 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 flex items-center justify-between gap-2 group"
															>
																<span className="flex items-center gap-2">
																	<span className="w-1 h-1 rounded-full bg-blue-300 group-hover:bg-blue-500 shrink-0 transition-colors" aria-hidden="true" />
																	{item.label}
																</span>
																<svg className="w-3 h-3 text-slate-300 group-hover:text-blue-400 shrink-0 transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true">
																	<path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 5l7 7-7 7" />
																</svg>
															</button>
														</li>
													))}
												</ul>
											)}
										</li>
									);
								})}
							</ul>
							<div className="border-t border-slate-100 pt-4 flex flex-col gap-3">
								<a
									href={waMsg(
										"Hi KESHAV ENTERPRISES, I would like to get a technical quote.",
									)}
									target="_blank"
									rel="noopener noreferrer"
									className="flex items-center justify-center gap-2 bg-[#25D366] text-white px-5 py-3.5 rounded-xl text-sm font-black tracking-wide shadow-md"
								>
									<MessageCircle className="w-5 h-5" aria-hidden="true" />{" "}
									WhatsApp Us
								</a>
								<a
									href={`tel:${CONTACT_INFO.phones[0].replace(/\s/g, "")}`}
									className={`flex items-center justify-center gap-2 px-5 py-3.5 rounded-xl text-sm font-black tracking-wide border transition-all ${
										scrolled
											? "bg-slate-900 text-white border-slate-800 hover:bg-blue-700"
											: "bg-slate-900 text-white border-slate-700"
									}`}
								>
									<Phone className="w-4 h-4" aria-hidden="true" />{" "}
									{CONTACT_INFO.phones[0]}
								</a>
							</div>
						</div>
					)}
				</div>
			)}
		</nav>
	);
});
Navbar.displayName = "Navbar";

// ─── CREDENTIAL BADGE (footer trust blocks) ──────────────────
const CredentialBadge = memo(({ imgSrc, Icon, iconColor, title, sub }) => {
	const [imgErr, setImgErr] = useState(false);
	return (
		<div className="flex items-center gap-3 rounded-xl px-3 py-2 w-fit transition-all duration-200 cursor-default ke-cred-badge">
			<div className="w-9 h-9 shrink-0 flex items-center justify-center bg-white rounded-lg p-1.5 border border-slate-200 shadow-inner">
				{!imgErr ? (
					<img
						src={imgSrc}
						alt={title}
						className="w-full h-full object-contain"
						onError={() => setImgErr(true)}
					/>
				) : (
					<Icon className={`w-5 h-5 ${iconColor}`} aria-hidden="true" />
				)}
			</div>
			<div>
				<p className="text-white font-bold text-xs uppercase tracking-wider leading-none mb-0.5">
					{title}
				</p>
				<p
					className="font-mono text-[10px] tracking-widest leading-none"
					style={{ color: "#06B6D4" }}
				>
					{sub}
				</p>
			</div>
		</div>
	);
});
CredentialBadge.displayName = "CredentialBadge";

// ─── FOOTER BADGE (credential blocks in footer col 1) ────────────
// Extracted from an inline .map() callback so useState is called at
// the top level of a proper component (rules-of-hooks compliance).
const FooterBadge = memo(
	({ imgSrc, FallbackIcon, title, sub, accentColor }) => {
		const [err, setErr] = useState(false);
		return (
			<div className="ke-badge">
				{/* Logo container */}
				<div
					style={{
						width: "2rem",
						height: "2rem",
						borderRadius: ".45rem",
						background: "#ffffff",
						border: `1px solid ${accentColor}25`,
						display: "flex",
						alignItems: "center",
						justifyContent: "center",
						flexShrink: 0,
						padding: "2px",
					}}
				>
					{!err ? (
						<img
							src={imgSrc}
							alt=""
							aria-hidden="true"
							style={{
								width: "1.6rem",
								height: "1.6rem",
								objectFit: "contain",
							}}
							onError={() => setErr(true)}
						/>
					) : (
						<FallbackIcon
							aria-hidden="true"
							style={{ width: "1.1rem", height: "1.1rem", color: accentColor }}
						/>
					)}
				</div>
				{/* Text */}
				<div style={{ minWidth: 0, flex: 1 }}>
					<p
						style={{
							margin: 0,
							fontSize: ".78rem",
							fontWeight: 700,
							color: "#e2e8f0",
							lineHeight: 1.25,
						}}
					>
						{title}
					</p>
					<p
						style={{
							margin: "2px 0 0",
							fontSize: ".68rem",
							color: "#64748b",
							lineHeight: 1.4,
							overflow: "hidden",
							textOverflow: "ellipsis",
							whiteSpace: "nowrap",
						}}
					>
						{sub}
					</p>
				</div>
				{/* Accent dot */}
				<div
					style={{
						width: "6px",
						height: "6px",
						borderRadius: "50%",
						background: accentColor,
						flexShrink: 0,
						opacity: 0.8,
					}}
					aria-hidden="true"
				/>
			</div>
		);
	},
);
FooterBadge.displayName = "FooterBadge";

