// ─── REPORT ISSUE MODAL ───────────────────────────────────────
// Reusable modal for reporting issues on Product or Service pages.
// Props:
//   context  — { type: 'product'|'service', name: string, id: string }
//   onClose  — function to close the modal
const ISSUE_TYPES = [
	{
		id: "wrong_info",
		label: "Wrong / missing info",
		icon: "📋",
		severity: "low",
	},
	{
		id: "quality",
		label: "Service quality complaint",
		icon: "⚠️",
		severity: "high",
	},
	{
		id: "delivery",
		label: "Delivery / order issue",
		icon: "🚚",
		severity: "high",
	},
	{
		id: "safety",
		label: "Technical / safety concern",
		icon: "🔴",
		severity: "critical",
	},
	{ id: "pricing", label: "Pricing dispute", icon: "💰", severity: "medium" },
	{ id: "feedback", label: "General feedback", icon: "💬", severity: "low" },
];

const SEVERITY_CONFIG = {
	low: { label: "Low", color: "bg-slate-100 text-slate-700 border-slate-200" },
	medium: {
		label: "Medium",
		color: "bg-amber-50 text-amber-800 border-amber-200",
	},
	high: {
		label: "High",
		color: "bg-orange-50 text-orange-800 border-orange-200",
	},
	critical: {
		label: "Critical",
		color: "bg-red-50 text-red-800 border-red-200",
	},
};

const ReportIssueModal = memo(({ context, onClose }) => {
	const [step, setStep] = useState(1); // 1=type, 2=details, 3=contact, 4=done
	const [issueType, setIssueType] = useState(null);
	const [description, setDescription] = useState("");
	const [name, setName] = useState("");
	const [phone, setPhone] = useState("");
	const [descErr, setDescErr] = useState("");
	const modalRef = useRef(null);

	// Focus trap — keeps Tab/Shift+Tab inside the dialog
	useFocusTrap(modalRef, true);

	// Close on Escape
	useEffect(() => {
		const h = (e) => {
			if (e.key === "Escape") onClose();
		};
		document.addEventListener("keydown", h);
		return () => document.removeEventListener("keydown", h);
	}, [onClose]);

	// Lock body scroll
	useEffect(() => {
		document.body.style.overflow = "hidden";
		return () => {
			document.body.style.overflow = "";
		};
	}, []);

	const selectedType = ISSUE_TYPES.find((t) => t.id === issueType);
	const severityConf = selectedType
		? SEVERITY_CONFIG[selectedType.severity]
		: null;

	const handleSubmit = useCallback(() => {
		// Rate limit: max 3 reports per hour per browser
		try {
			const RL_KEY = "ke_report_ts";
			const now = Date.now();
			const stored = JSON.parse(localStorage.getItem(RL_KEY) || "[]");
			const recent = stored.filter((t) => now - t < 60 * 60 * 1000); // last 1 hour
			if (recent.length >= 3) {
				setDescErr(
					"You have submitted 3 reports in the last hour. Please try again later or call us directly.",
				);
				return;
			}
			recent.push(now);
			localStorage.setItem(RL_KEY, JSON.stringify(recent));
		} catch {
			/* localStorage blocked — allow submission */
		}

		if (description.trim().length < 15) {
			setDescErr("Please describe the issue in at least 15 characters.");
			return;
		}
		setDescErr("");

		const lines = [
			`⚠️ *Issue Report — Keshav Enterprises*`,
			``,
			`*${context.type === "product" ? "Product" : "Service"}:* ${sanitise(context.name)}`,
			`*Issue Type:* ${selectedType?.label || "General"}`,
			`*Severity:* ${severityConf?.label || "Low"}`,
			``,
			`*Description:*`,
			sanitise(description),
		];
		if (name.trim()) lines.push(``, `*Reported by:* ${sanitise(name)}`);
		if (phone.trim()) lines.push(`*Contact:* ${sanitise(phone)}`);

		window.open(waMsg(lines.join("\n")), "_blank", "noopener");
		setStep(4);
	}, [context, selectedType, severityConf, description, name, phone]);

	// Step labels for progress indicator
	const steps = ["Issue type", "Details", "Contact", "Done"];

	return (
		<div
			className="fixed inset-0 z-9999 flex items-end sm:items-center justify-center p-4"
			role="dialog"
			aria-modal="true"
			aria-labelledby="report-modal-title"
		>
			{/* Backdrop */}
			<div
				className="absolute inset-0 bg-black/50 backdrop-blur-sm"
				onClick={onClose}
				aria-hidden="true"
			/>

			{/* Panel */}
			<div
				ref={modalRef}
				className="relative bg-white rounded-2xl shadow-2xl w-full max-w-lg max-h-[92vh] flex flex-col overflow-hidden"
				tabIndex={-1}
			>
				{/* Header */}
				<div className="flex items-center justify-between px-6 py-4 border-b border-slate-100 shrink-0">
					<div className="flex items-center gap-3">
						<div className="w-9 h-9 bg-orange-100 rounded-xl flex items-center justify-center shrink-0">
							<Flag className="w-4 h-4 text-orange-500" aria-hidden="true" />
						</div>
						<div>
							<h2
								id="report-modal-title"
								className="font-black text-slate-900 text-base leading-tight"
							>
								Report an Issue
							</h2>
							<p className="text-xs text-slate-500 font-medium truncate max-w-60">
								{context.name}
							</p>
						</div>
					</div>
					<button
						type="button"
						onClick={onClose}
						className="w-9 h-9 flex items-center justify-center rounded-xl hover:bg-slate-100 transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-slate-400"
						aria-label="Close report modal"
					>
						<X className="w-5 h-5 text-slate-500" aria-hidden="true" />
					</button>
				</div>

				{/* Progress bar — steps 1-3 only */}
				{step < 4 && (
					<div className="px-6 pt-4 pb-2 shrink-0">
						<div className="flex items-center gap-2">
							{steps.slice(0, 3).map((label, i) => {
								const idx = i + 1;
								const active = step === idx;
								const done = step > idx;
								return (
									<React.Fragment key={label}>
										<div className="flex items-center gap-1.5 shrink-0">
											<div
												className={`w-5 h-5 rounded-full flex items-center justify-center text-[10px] font-black transition-all ${done ? "bg-blue-600 text-white" : active ? "bg-blue-100 text-blue-700 ring-2 ring-blue-300" : "bg-slate-100 text-slate-400"}`}
											>
												{done ? (
													<CheckCircle2
														className="w-3 h-3"
														aria-hidden="true"
													/>
												) : (
													idx
												)}
											</div>
											<span
												className={`text-xs font-bold hidden sm:block ${active ? "text-blue-700" : done ? "text-slate-500" : "text-slate-300"}`}
											>
												{label}
											</span>
										</div>
										{i < 2 && (
											<div
												className={`flex-1 h-0.5 rounded-full transition-all ${done ? "bg-blue-500" : "bg-slate-200"}`}
												aria-hidden="true"
											/>
										)}
									</React.Fragment>
								);
							})}
						</div>
					</div>
				)}

				{/* Body — scrollable */}
				<div className="flex-1 overflow-y-auto px-6 py-4">
					{/* ── STEP 1: Issue type ── */}
					{step === 1 && (
						<div>
							<p className="text-sm font-bold text-slate-700 mb-4">
								What kind of issue are you reporting?
							</p>
							<div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
								{ISSUE_TYPES.map((type) => (
									<button
										key={type.id}
										type="button"
										onClick={() => setIssueType(type.id)}
										className={`flex items-center gap-3 p-4 rounded-xl border-2 text-left transition-all focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-400 ${
											issueType === type.id
												? "border-blue-500 bg-blue-50"
												: "border-slate-200 hover:border-blue-300 hover:bg-slate-50"
										}`}
										aria-pressed={issueType === type.id}
									>
										<span className="text-xl shrink-0" aria-hidden="true">
											{type.icon}
										</span>
										<span className="text-sm font-bold text-slate-800 leading-snug">
											{type.label}
										</span>
									</button>
								))}
							</div>
							{/* Safety notice */}
							{issueType === "safety" && (
								<div className="mt-4 flex gap-3 bg-red-50 border border-red-200 rounded-xl p-4">
									<AlertTriangle
										className="w-5 h-5 text-red-500 shrink-0 mt-0.5"
										aria-hidden="true"
									/>
									<p className="text-sm font-bold text-red-700 leading-snug">
										For immediate safety risks, please call us directly at{" "}
										<a
											href={`tel:${CONTACT_INFO.phones[0].replace(/\s/g, "")}`}
											className="underline"
										>
											{CONTACT_INFO.phones[0]}
										</a>
										. This form is for non-emergency reporting.
									</p>
								</div>
							)}
						</div>
					)}

					{/* ── STEP 2: Details ── */}
					{step === 2 && selectedType && (
						<div>
							{/* Severity badge */}
							<div
								className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-full border text-xs font-black uppercase tracking-widest mb-5 ${severityConf.color}`}
							>
								{selectedType.icon} {selectedType.label} · {severityConf.label}{" "}
								priority
							</div>

							<label
								htmlFor="ri-description"
								className="block text-sm font-bold text-slate-700 mb-2"
							>
								Describe the issue{" "}
								<span className="text-red-500" aria-hidden="true">
									*
								</span>
							</label>
							<textarea
								id="ri-description"
								rows={5}
								value={description}
								onChange={(e) => {
									setDescription(e.target.value);
									if (descErr) setDescErr("");
								}}
								placeholder={
									issueType === "wrong_info"
										? "Which information is wrong or missing? Where did you see it?"
										: issueType === "quality"
											? "What happened during the service? When and where?"
											: issueType === "delivery"
												? "What was ordered? What went wrong with delivery?"
												: issueType === "safety"
													? "Describe the safety concern clearly. Include part numbers if relevant."
													: issueType === "pricing"
														? "Which product or service? What price discrepancy did you notice?"
														: "Share your feedback — what can we improve?"
								}
								aria-required="true"
								aria-invalid={!!descErr}
								aria-describedby={descErr ? "ri-desc-err" : undefined}
								className={`w-full px-4 py-3 bg-slate-50 border rounded-xl font-medium text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all resize-none ${descErr ? "border-red-400 bg-red-50" : "border-slate-200"}`}
							/>
							<div className="flex justify-between mt-1">
								{descErr ? (
									<p
										id="ri-desc-err"
										role="alert"
										className="text-red-500 text-xs font-bold"
									>
										{descErr}
									</p>
								) : (
									<span />
								)}
								<span
									className={`text-xs font-medium ${description.length < 15 ? "text-slate-400" : "text-green-600"}`}
								>
									{description.length} chars
								</span>
							</div>
						</div>
					)}

					{/* ── STEP 3: Contact (optional) ── */}
					{step === 3 && (
						<div className="flex flex-col gap-5">
							<div className="bg-blue-50 border border-blue-100 rounded-xl p-4 flex gap-3">
								<Shield
									className="w-5 h-5 text-blue-500 shrink-0 mt-0.5"
									aria-hidden="true"
								/>
								<p className="text-sm font-medium text-blue-800 leading-snug">
									Your contact details are <strong>optional</strong> and used
									only to follow up on your report. You can submit anonymously.
								</p>
							</div>
							<div>
								<label
									htmlFor="ri-name"
									className="block text-xs font-black text-slate-500 uppercase tracking-widest mb-2"
								>
									Your name{" "}
									<span className="text-slate-400 font-medium normal-case tracking-normal">
										(optional)
									</span>
								</label>
								<input
									id="ri-name"
									type="text"
									value={name}
									onChange={(e) => setName(e.target.value)}
									placeholder="Company or contact name"
									className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-medium text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all"
								/>
							</div>
							<div>
								<label
									htmlFor="ri-phone"
									className="block text-xs font-black text-slate-500 uppercase tracking-widest mb-2"
								>
									Phone / WhatsApp{" "}
									<span className="text-slate-400 font-medium normal-case tracking-normal">
										(optional)
									</span>
								</label>
								<input
									id="ri-phone"
									type="tel"
									value={phone}
									onChange={(e) => setPhone(e.target.value)}
									placeholder="+91 XXXXX XXXXX"
									className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-medium text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all"
								/>
							</div>
						</div>
					)}

					{/* ── STEP 4: Done ── */}
					{step === 4 && (
						<div className="py-6 text-center flex flex-col items-center gap-4">
							<div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center">
								<CheckCircle2
									className="w-8 h-8 text-green-500"
									aria-hidden="true"
								/>
							</div>
							<div>
								<h3 className="font-black text-slate-900 text-xl mb-2">
									Report submitted
								</h3>
								<p className="text-slate-500 font-medium text-sm leading-relaxed max-w-xs mx-auto">
									Your report has been sent to our engineering team via
									WhatsApp. We take all feedback seriously and will review it
									promptly.
								</p>
							</div>
							{selectedType?.severity === "critical" && (
								<div className="bg-red-50 border border-red-200 rounded-xl p-4 max-w-xs text-left">
									<p className="text-sm font-bold text-red-700">
										For urgent safety concerns, also call us directly:{" "}
										<a
											href={`tel:${CONTACT_INFO.phones[0].replace(/\s/g, "")}`}
											className="underline"
										>
											{CONTACT_INFO.phones[0]}
										</a>
									</p>
								</div>
							)}
							<button
								type="button"
								onClick={onClose}
								className="bg-blue-600 text-white px-8 py-3 rounded-xl font-black text-sm hover:bg-blue-500 transition-all focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-300"
							>
								Close
							</button>
						</div>
					)}
				</div>

				{/* Footer navigation — steps 1-3 */}
				{step < 4 && (
					<div className="px-6 py-4 border-t border-slate-100 flex justify-between items-center shrink-0 gap-3">
						<button
							type="button"
							onClick={() => (step === 1 ? onClose() : setStep((s) => s - 1))}
							className="px-5 py-2.5 rounded-xl border border-slate-200 font-bold text-sm text-slate-700 hover:bg-slate-50 transition-all focus:outline-none focus-visible:ring-2 focus-visible:ring-slate-400"
						>
							{step === 1 ? "Cancel" : "← Back"}
						</button>

						{step < 3 ? (
							<button
								type="button"
								disabled={step === 1 && !issueType}
								onClick={() => {
									if (step === 2) {
										if (description.trim().length < 15) {
											setDescErr(
												"Please describe the issue in at least 15 characters.",
											);
											return;
										}
										setDescErr("");
									}
									setStep((s) => s + 1);
								}}
								className="px-6 py-2.5 rounded-xl bg-blue-600 text-white font-black text-sm hover:bg-blue-500 transition-all disabled:opacity-40 disabled:cursor-not-allowed focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-300 flex items-center gap-2"
							>
								Continue <ArrowRight className="w-4 h-4" aria-hidden="true" />
							</button>
						) : (
							<button
								type="button"
								onClick={handleSubmit}
								className="px-6 py-2.5 rounded-xl bg-[#25D366] text-white font-black text-sm hover:bg-[#1ebe5d] transition-all focus:outline-none focus-visible:ring-2 focus-visible:ring-green-400 flex items-center gap-2 shadow-[0_4px_16px_rgba(37,211,102,0.3)]"
							>
								<MessageCircle className="w-4 h-4" aria-hidden="true" />
								Send via WhatsApp
							</button>
						)}
					</div>
				)}
			</div>
		</div>
	);
});
ReportIssueModal.displayName = "ReportIssueModal";

// ─── FLOATING BUTTONS ─────────────────────────────────────────
// ─── RECENTLY VIEWED PRODUCTS ────────────────────────────────
// Stores up to 6 product IDs in localStorage, newest first.
const RV_KEY = "ke_recently_viewed";
const RV_MAX = 6;

const getRecentlyViewed = () => {
	try {
		const parsed = JSON.parse(localStorage.getItem(RV_KEY) || "[]");
		return Array.isArray(parsed) ? parsed : [];
	} catch {
		return [];
	}
};

const addRecentlyViewed = (productId) => {
	try {
		const list = getRecentlyViewed().filter((id) => id !== productId);
		list.unshift(productId);
		localStorage.setItem(RV_KEY, JSON.stringify(list.slice(0, RV_MAX)));
	} catch {
		/* ignore */
	}
};

const RecentlyViewedStrip = memo(({ currentProductId, navigate }) => {
	// Derive directly — no state, no effect, no cascading renders.
	// useMemo re-runs whenever currentProductId changes (i.e. user navigates
	// to a different product), which is the only time this list can change.
	const items = useMemo(
		() =>
			getRecentlyViewed()
				.filter((id) => id !== currentProductId)
				.map((id) => PRODUCTS.find((p) => p.id === id))
				.filter(Boolean)
				.slice(0, 4),
		[currentProductId],
	);

	if (items.length === 0) return null;

	return (
		<section
			aria-labelledby="rv-heading"
			className="mt-12 pt-8 border-t border-slate-100"
		>
			<h2
				id="rv-heading"
				className="text-xl font-black text-slate-900 tracking-tight mb-5 flex items-center gap-2"
			>
				<Clock className="w-5 h-5 text-blue-500" aria-hidden="true" />
				Recently Viewed
			</h2>
			<div className="grid grid-cols-2 md:grid-cols-4 gap-4">
				{items.map((p) => {
					const img = p.images?.[0];
					return (
						<button
							key={p.id}
							type="button"
							onClick={() => navigate(`/product/${p.id}`)}
							className="group flex flex-col bg-white border border-slate-200 rounded-xl overflow-hidden shadow-sm hover:shadow-md hover:border-blue-300 hover:-translate-y-0.5 transition-all text-left focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-500"
							aria-label={`View ${p.title}`}
						>
							<div className="h-28 bg-slate-50 flex items-center justify-center p-3 border-b border-slate-100">
								{img ? (
									<img
										src={img}
										alt={`${p.title} — ${p.category}`}
										loading="lazy"
										className="max-h-full max-w-full object-contain"
										onError={(e) => {
											e.target.style.display = "none";
										}}
									/>
								) : (
									<div
										className="w-10 h-10 bg-slate-200 rounded-lg"
										aria-hidden="true"
									/>
								)}
							</div>
							<div className="p-3 flex-1 flex flex-col">
								<span className="text-[10px] font-black text-blue-600 uppercase tracking-widest mb-1">
									{p.category}
								</span>
								<p className="text-xs font-bold text-slate-800 leading-snug line-clamp-2 group-hover:text-blue-700 transition-colors">
									{p.title}
								</p>
							</div>
						</button>
					);
				})}
			</div>
		</section>
	);
});
RecentlyViewedStrip.displayName = "RecentlyViewedStrip";

// ─── BACK TO TOP BUTTON ───────────────────────────────────────
const BackToTopButton = memo(() => {
	const [visible, setVisible] = useState(false);
	const [progress, setProgress] = useState(0);

	useEffect(() => {
		const onScroll = () => {
			const scrollY = window.scrollY;
			const docH = document.documentElement.scrollHeight - window.innerHeight;
			setVisible(scrollY > 400);
			setProgress(docH > 0 ? Math.min(100, (scrollY / docH) * 100) : 0);
		};
		window.addEventListener("scroll", onScroll, { passive: true });
		onScroll();
		return () => window.removeEventListener("scroll", onScroll);
	}, []);

	return (
		<button
			type="button"
			onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })}
			aria-label="Back to top"
			style={{
				position: "fixed",
				bottom: "1.5rem",
				left: "1.5rem",
				zIndex: 50,
				width: "2.75rem",
				height: "2.75rem",
				background: "#0f172a",
				borderRadius: "50%",
				display: "flex",
				alignItems: "center",
				justifyContent: "center",
				boxShadow: "0 4px 14px rgba(0,0,0,0.25)",
				transition: "opacity .25s ease, transform .25s ease, background .2s",
				opacity: visible ? 1 : 0,
				transform: visible
					? "translateY(0) scale(1)"
					: "translateY(10px) scale(0.85)",
				pointerEvents: visible ? "auto" : "none",
				border: "none",
				cursor: "pointer",
			}}
			onMouseEnter={(e) => {
				e.currentTarget.style.background = "#2563eb";
				e.currentTarget.style.transform = "translateY(-2px) scale(1.08)";
			}}
			onMouseLeave={(e) => {
				e.currentTarget.style.background = "#0f172a";
				e.currentTarget.style.transform = visible
					? "translateY(0) scale(1)"
					: "translateY(10px) scale(0.85)";
			}}
		>
			{/* Circular progress ring */}
			<svg
				width="44"
				height="44"
				viewBox="0 0 44 44"
				style={{ position: "absolute", inset: 0, transform: "rotate(-90deg)" }}
				aria-hidden="true"
			>
				<circle
					cx="22"
					cy="22"
					r="19"
					fill="none"
					stroke="rgba(255,255,255,0.1)"
					strokeWidth="2.5"
				/>
				<circle
					cx="22"
					cy="22"
					r="19"
					fill="none"
					stroke="#3b82f6"
					strokeWidth="2.5"
					strokeDasharray={`${2 * Math.PI * 19}`}
					strokeDashoffset={`${2 * Math.PI * 19 * (1 - progress / 100)}`}
					strokeLinecap="round"
					style={{ transition: "stroke-dashoffset .1s linear" }}
				/>
			</svg>
			<ChevronUp
				className="w-4 h-4 text-white relative z-10"
				aria-hidden="true"
			/>
		</button>
	);
});
BackToTopButton.displayName = "BackToTopButton";

// ─── WHATSAPP CHAT BUBBLE ─────────────────────────────────────
// Timing constants — tweak here without touching logic
const WA_GREETING_DELAY = 4000; // ms after mount before first appearance
const WA_GREETING_VISIBLE = 6000; // ms the bubble stays visible before auto-hiding
const WA_GREETING_INTERVAL = 25000; // ms between re-appearances (if not dismissed for session)

const WhatsAppBubble = memo(() => {
	const [showGreeting, setShowGreeting] = useState(false);
	const [sessionDone, setSessionDone] = useState(() => {
		try {
			return !!sessionStorage.getItem("ke_wa_dismissed");
		} catch {
			return false;
		}
	});

	// Refs hold every timer so cleanup always reaches them, even timers
	// created inside nested callbacks (local `let` vars get captured at closure
	// creation time — before the inner setTimeout fires — so clearTimeout
	// would clear `undefined` and the repeat timer would leak forever).
	const showTimerRef = useRef(null);
	const hideTimerRef = useRef(null);
	const repeatTimerRef = useRef(null);

	const clearAll = useCallback(() => {
		clearTimeout(showTimerRef.current);
		clearTimeout(hideTimerRef.current);
		clearTimeout(repeatTimerRef.current);
	}, []);

	useEffect(() => {
		if (sessionDone) return;

		const showBubble = () => {
			setShowGreeting(true);
			hideTimerRef.current = setTimeout(() => {
				setShowGreeting(false);
				repeatTimerRef.current = setTimeout(showBubble, WA_GREETING_INTERVAL);
			}, WA_GREETING_VISIBLE);
		};

		showTimerRef.current = setTimeout(showBubble, WA_GREETING_DELAY);

		return clearAll;
	}, [sessionDone, clearAll]);

	const dismiss = useCallback(
		(e) => {
			e.preventDefault();
			e.stopPropagation();
			clearAll(); // cancel any pending show/hide/repeat
			setShowGreeting(false);
			setSessionDone(true);
			try {
				sessionStorage.setItem("ke_wa_dismissed", "1");
			} catch {
				/* ignore */
			}
		},
		[clearAll],
	);

	return (
		<div className="fixed bottom-6 right-6 z-50 flex flex-col items-end gap-2">
			{/* Greeting bubble */}
			{showGreeting && (
				<div
					className="relative bg-white border border-slate-200 rounded-2xl rounded-br-sm shadow-xl px-4 py-3 max-w-55 animate-[fadeSlideUp_0.35s_ease_forwards]"
					role="status"
					aria-live="polite"
				>
					<button
						type="button"
						onClick={dismiss}
						aria-label="Dismiss greeting"
						className="absolute -top-2 -right-2 w-5 h-5 bg-slate-500 hover:bg-slate-700 text-white rounded-full flex items-center justify-center transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-slate-400"
					>
						<X className="w-3 h-3" />
					</button>
					<p className="text-xs font-black text-slate-900 mb-0.5">👋 Hello!</p>
					<p className="text-xs font-medium text-slate-600 leading-snug">
						Need a quote or tech support? Chat with our engineers now.
					</p>
					{/* Chat bubble tail */}
					<span
						className="absolute bottom-0 right-3 translate-y-full w-0 h-0 border-l-8 border-r-0 border-t-8 border-l-transparent border-t-white"
						aria-hidden="true"
					/>
				</div>
			)}

			{/* Phone pill */}
			<a
				href={`tel:${CONTACT_INFO.phones[0].replace(/\s/g, "")}`}
				className="flex items-center justify-center gap-2 bg-white border border-slate-200 text-slate-900 p-3.5 rounded-full shadow-lg hover:bg-slate-50 hover:scale-105 transition-all group font-bold text-sm"
				aria-label={`Call Keshav Enterprises: ${CONTACT_INFO.phones[0]}`}
			>
				<Phone
					className="w-4 h-4 text-blue-600 shrink-0 translate-x-px"
					aria-hidden="true"
				/>
				<span className="max-w-0 overflow-hidden group-hover:max-w-xs transition-all duration-300 whitespace-nowrap">
					{CONTACT_INFO.phones[0]}
				</span>
			</a>

			{/* WhatsApp FAB — with hover label for discoverability */}
			<a
				href={waMsg(
					"Hi KESHAV ENTERPRISES, I would like to request a technical quote.",
				)}
				target="_blank"
				rel="noopener noreferrer"
				aria-label="Chat with Keshav Enterprises on WhatsApp"
				onClick={() => setShowGreeting(false)}
				className="ke-wa-fab flex items-center gap-2 bg-[#25D366] text-white pl-3.5 pr-4 py-3.5 rounded-full shadow-[0_0_16px_rgba(37,211,102,0.4)] hover:bg-[#1ebe5d] transition-all duration-300 focus:outline-none focus-visible:ring-2 focus-visible:ring-green-400"
			>
				<MessageCircle className="w-6 h-6 shrink-0" aria-hidden="true" />
				<span className="ke-wa-label" aria-hidden="true">
					Chat
				</span>
			</a>
		</div>
	);
});
WhatsAppBubble.displayName = "WhatsAppBubble";

const FloatingButtons = memo(() => <WhatsAppBubble />);
FloatingButtons.displayName = "FloatingButtons";

// ─── INLINE RFQ FORM ─────────────────────────────────────────
// Embedded quote request form on product detail pages.
// Submits via Web3Forms (same key as the contact page).
// No file upload — keeps the form lightweight for procurement managers on work devices.
const InlineRFQForm = memo(({ productTitle }) => {
	const [open, setOpen] = useState(false);
	const [name, setName] = useState("");
	const [company, setCompany] = useState("");
	const [email, setEmail] = useState("");
	const [phone, setPhone] = useState("");
	const [qty, setQty] = useState("");
	const [message, setMessage] = useState("");
	const [status, setStatus] = useState("idle"); // idle | sending | success | error
	const [errMsg, setErrMsg] = useState("");
	const [turnstileToken, setTurnstileToken] = useState("");
	const formRef = useRef(null);
	useFocusTrap(formRef, open);

	// Strip HTML tags, script injection chars, and WhatsApp markdown before
	// sending to Web3Forms — mirrors the module-level sanitise helper.
	const sanitise = (s) =>
		String(s ?? "")
			.replace(/<[^>]*>/g, "") // strip HTML tags
			.replace(/[<>"'`]/g, "") // strip injection chars
			.replace(/[*_~]/g, "") // strip WA markdown
			.trim()
			.slice(0, 500);

	const reset = useCallback(() => {
		setName("");
		setCompany("");
		setEmail("");
		setPhone("");
		setQty("");
		setMessage("");
		setStatus("idle");
		setErrMsg("");
	}, []);

	const handleSubmit = useCallback(async () => {
		const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim());
		if (!name.trim()) {
			setErrMsg("Name is required.");
			return;
		}
		if (!emailOk) {
			setErrMsg("Please enter a valid email address.");
			return;
		}
		if (!checkFormRateLimit("ke_rfq_ts", 5, 3_600_000)) {
			setErrMsg("Too many submissions. Please wait an hour before trying again.");
			return;
		}
		if (TURNSTILE_SITE_KEY && !turnstileToken) {
			setErrMsg("Please complete the security check.");
			return;
		}
		setStatus("sending");
		setErrMsg("");
		// Guard: if key is not configured, surface a clear message instead of a silent API failure
		if (!WEB3FORMS_KEY) {
			setErrMsg("Form not configured — please contact us directly via WhatsApp or phone.");
			setStatus("error");
			return;
		}
		try {
			const fd = new FormData();
			fd.append("access_key", WEB3FORMS_KEY);
			// Honeypot — Web3Forms discards submissions where this field is non-empty
			fd.append("botcheck", "");
			if (turnstileToken) fd.append("cf-turnstile-response", turnstileToken);
			fd.append("from_name", "Keshav Enterprises Website");
			fd.append("Product", sanitise(productTitle));
			fd.append("Name", sanitise(name));
			fd.append("Company", sanitise(company));
			fd.append("Email", sanitise(email));
			fd.append("Phone", sanitise(phone));
			fd.append("Quantity", sanitise(qty));
			fd.append("Message", sanitise(message));
			const res = await fetch("https://api.web3forms.com/submit", {
				method: "POST",
				headers: { Accept: "application/json" },
				body: fd,
			});
			const data = await res.json();
			if (!res.ok || data.success === false)
				throw new Error(data.message || "Submission failed");
			setStatus("success");
		} catch (err) {
			setErrMsg(err.message || "Something went wrong. Please try again.");
			setStatus("error");
		}
	}, [name, company, email, phone, qty, message, productTitle, turnstileToken]);

	const clearErr = useCallback(() => {
		if (status === "error" || errMsg) {
			setStatus("idle");
			setErrMsg("");
		}
	}, [status, errMsg]);
	const inputCls =
		"w-full rounded-lg border border-slate-200 bg-white px-3.5 py-2.5 text-sm text-slate-900 placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-shadow";
	const labelCls =
		"block text-xs font-black text-slate-500 uppercase tracking-widest mb-1";

	return (
		<div className="mt-5 border-2 border-blue-100 rounded-2xl overflow-hidden bg-blue-50/40">
			{/* Toggle header */}
			<button
				type="button"
				onClick={() => {
					setOpen((o) => !o);
					if (!open) reset();
				}}
				aria-expanded={open}
				aria-controls="rfq-form-body"
				className="w-full flex items-center justify-between px-5 py-4 text-left focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 rounded-2xl"
			>
				<span className="flex items-center gap-3">
					<Mail className="w-5 h-5 text-blue-600 shrink-0" aria-hidden="true" />
					<span className="font-black text-slate-800 text-sm tracking-tight">
						Request a Quote by Email
					</span>
					<span className="hidden sm:inline text-xs text-slate-500 font-medium">
						— no WhatsApp needed
					</span>
				</span>
				<svg
					aria-hidden="true"
					className={`w-4 h-4 text-blue-500 transition-transform duration-200 ${open ? "rotate-180" : ""}`}
					fill="none"
					stroke="currentColor"
					viewBox="0 0 24 24"
				>
					<path
						strokeLinecap="round"
						strokeLinejoin="round"
						strokeWidth={2.5}
						d="M19 9l-7 7-7-7"
					/>
				</svg>
			</button>

			{/* Collapsible body */}
			{open && (
				<div
					id="rfq-form-body"
					ref={formRef}
					className="px-5 pb-5 pt-1 border-t border-blue-100"
				>
					{status === "success" ? (
						<div className="flex flex-col items-center gap-3 py-8 text-center">
							<CheckCircle2
								className="w-12 h-12 text-green-500"
								aria-hidden="true"
							/>
							<p className="font-black text-slate-800 text-base">
								Quote request sent!
							</p>
							<p className="text-sm text-slate-500">
								We'll get back to you within 1 business day.
							</p>
							<button
								type="button"
								onClick={reset}
								className="mt-2 text-blue-600 text-sm font-bold hover:underline focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 rounded"
							>
								Send another request
							</button>
						</div>
					) : (
						<div className="mt-4 grid grid-cols-1 sm:grid-cols-2 gap-4">
							<div>
								<label htmlFor="rfq-name" className={labelCls}>
									Name <span className="text-red-500">*</span>
								</label>
								<input
									id="rfq-name"
									type="text"
									autoComplete="name"
									value={name}
									onChange={(e) => {
										setName(e.target.value);
										clearErr();
									}}
									placeholder="Your name"
									className={inputCls}
								/>
							</div>
							<div>
								<label htmlFor="rfq-company" className={labelCls}>
									Company
								</label>
								<input
									id="rfq-company"
									type="text"
									autoComplete="organization"
									value={company}
									onChange={(e) => {
										setCompany(e.target.value);
										clearErr();
									}}
									placeholder="Company name"
									className={inputCls}
								/>
							</div>
							<div>
								<label htmlFor="rfq-email" className={labelCls}>
									Email <span className="text-red-500">*</span>
								</label>
								<input
									id="rfq-email"
									type="email"
									autoComplete="email"
									value={email}
									onChange={(e) => {
										setEmail(e.target.value);
										clearErr();
									}}
									placeholder="you@company.com"
									className={inputCls}
								/>
							</div>
							<div>
								<label htmlFor="rfq-phone" className={labelCls}>
									Phone
								</label>
								<input
									id="rfq-phone"
									type="tel"
									autoComplete="tel"
									value={phone}
									onChange={(e) => {
										setPhone(e.target.value);
										clearErr();
									}}
									placeholder="+91 98000 00000"
									className={inputCls}
								/>
							</div>
							<div className="sm:col-span-2">
								<label htmlFor="rfq-qty" className={labelCls}>
									Quantity / Requirement
								</label>
								<input
									id="rfq-qty"
									type="text"
									value={qty}
									onChange={(e) => {
										setQty(e.target.value);
										clearErr();
									}}
									placeholder="e.g. 10 units, DN 50, SS 316…"
									className={inputCls}
								/>
							</div>
							<div className="sm:col-span-2">
								<label htmlFor="rfq-message" className={labelCls}>
									Additional Details
								</label>
								<textarea
									id="rfq-message"
									rows={3}
									maxLength={1000}
									value={message}
									onChange={(e) => {
										setMessage(e.target.value);
										clearErr();
									}}
									placeholder="Application, pressure rating, delivery location, or any other specs…"
									className={`${inputCls} resize-none`}
								/>
							</div>

							{errMsg && (
								<div
									role="alert"
									className="sm:col-span-2 rounded-lg bg-red-50 border border-red-200 px-4 py-2.5 text-sm text-red-700 font-semibold flex items-center gap-2"
								>
									<AlertTriangle
										className="w-4 h-4 shrink-0"
										aria-hidden="true"
									/>
									{errMsg}
								</div>
							)}

							<div className="sm:col-span-2">
								<TurnstileWidget
									widgetId="rfq"
									onVerify={(token) => setTurnstileToken(token)}
									onExpire={() => setTurnstileToken("")}
								/>
								<button
									type="button"
									onClick={handleSubmit}
									disabled={status === "sending"}
									className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-blue-400 text-white font-black py-3.5 rounded-xl text-sm tracking-tight transition-all shadow-md hover:-translate-y-0.5 focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-400 flex items-center justify-center gap-2"
								>
									{status === "sending" ? (
										<>
											<svg
												className="animate-spin w-4 h-4"
												fill="none"
												viewBox="0 0 24 24"
												aria-hidden="true"
											>
												<circle
													className="opacity-25"
													cx="12"
													cy="12"
													r="10"
													stroke="currentColor"
													strokeWidth="4"
												/>
												<path
													className="opacity-75"
													fill="currentColor"
													d="M4 12a8 8 0 018-8v8z"
												/>
											</svg>
											Sending…
										</>
									) : (
										<>
											<Mail className="w-4 h-4" aria-hidden="true" />
											Send Quote Request
										</>
									)}
								</button>
								<p className="mt-2 text-center text-[11px] text-slate-400">
									We respond within 1 business day · No spam
								</p>
							</div>
						</div>
					)}
				</div>
			)}
		</div>
	);
});
