// ─── APP ROOT ─────────────────────────────────────────────────
// Paths where the exit-intent popup is suppressed (review form already present,
// or the page would feel intrusive). Defined at module level — stable reference.
const POPUP_EXCLUDED_PATHS = ["/contact", "/product/", "/service/", "/downloads"];

export default function App() {
	// Seed the initial history entry with idx:0 if it has none yet.
	// This ensures popstate always finds a numeric idx in event.state.
	// FIXED: moved into useEffect so it runs once on mount, not on every render.
	useEffect(() => {
		if (window.history.state?.idx === undefined) {
			window.history.replaceState({ idx: 0 }, "", window.location.href);
		}
	}, []);

	const [currentPath, setCurrentPath] = useState(() => {
		const p = window.location.hash.replace("#", "") || "/";
		return p.length > 1 ? p.replace(/\/+$/, "") : p;
	});
	// AUDIT FIX: aria-live region for screen reader route announcements
	const [routeAnnouncement, setRouteAnnouncement] = useState("");
	// Ref mirror of currentPath — lets navigate() read the latest path without
	// being listed as a dep (which would recreate navigate on every navigation).
	const currentPathRef = useRef("/");
	// Tracks the pending "clear announcement" timer so rapid navigation doesn't
	// stack multiple timers that blank a newer announcement prematurely.
	const announceClearTimer = useRef(null);
	useEffect(() => {
		currentPathRef.current = currentPath;
	}, [currentPath]);

	// ── Exit-intent popup route guard ──────────────────────────────
	// Suppresses the popup on pages where the review form already lives
	// or where it would feel intrusive (contact page).
	// (POPUP_EXCLUDED_PATHS is defined at module level above App.)
	const showExitPopup = !POPUP_EXCLUDED_PATHS.some((p) =>
		currentPath.startsWith(p),
	);

	// ── Scroll restoration ──────────────────────────────────────
	// scrollPositions[historyIdx] = scrollY for that history entry.
	// historyIdx is a monotonic counter we store in history.state.
	// On popstate we compare new idx to current idx to know direction:
	//   back  (newIdx < curIdx) → restore saved position
	//   forward (newIdx > curIdx) → scroll to top (new content)
	const scrollPositions = useRef({});
	const historyIdxRef = useRef(0); // idx of the currently visible entry
	const historyCounter = useRef(0); // ever-increasing, used when pushing new entries

	// Stable window listeners — registered once
	useEffect(() => {
		const h = (event) => {
			const raw = window.location.hash.replace("#", "") || "/";
			const newPath = raw.length > 1 ? raw.replace(/\/+$/, "") : raw;

			// Determine direction using the history index stored in state.
			const newIdx = event.state?.idx ?? 0;
			const curIdx = historyIdxRef.current;
			const isBack = newIdx < curIdx;

			// Save scroll of the page we're leaving before React re-renders it.
			scrollPositions.current[curIdx] = window.scrollY;

			// Update the current index reference.
			historyIdxRef.current = newIdx;

			setCurrentPath(newPath);

			// After React paints the restored/new page, apply scroll.
			requestAnimationFrame(() => {
				if (isBack) {
					// Back: restore saved position for this history entry.
					const saved = scrollPositions.current[newIdx] ?? 0;
					window.scrollTo({ top: saved, behavior: "instant" });
				} else {
					// Forward: always start at top.
					window.scrollTo({ top: 0, behavior: "instant" });
				}
			});

			// a11y: move focus to main content after back/forward navigation.
			// navigate() handles this for pushState; popstate (back/forward) needs its own call.
			setTimeout(() => document.getElementById("main-content")?.focus(), 100);
		};
		window.addEventListener("popstate", h);

		// ── PERF: Back/Forward Cache (bfcache) fix ──
		// Prevents "Page prevented back/forward cache restoration" Lighthouse warning.
		const handlePageHide = () => {
			/* intentionally empty — keeps bfcache eligible */
		};
		window.addEventListener("pagehide", handlePageHide);

		return () => {
			window.removeEventListener("popstate", h);
			window.removeEventListener("pagehide", handlePageHide);
		};
	}, []);

	// ── PERF: Inject hero image preload ONLY on homepage to avoid
	// "preloaded but not used" warning on other routes.
	// Filename matches the actual <img src> used in HomePage: hero-background.png
	useEffect(() => {
		const PRELOAD_ID = "hero-bg-preload";
		const PRELOAD_WEBP_ID = "hero-bg-preload-webp";
		if (currentPath === "/") {
			if (!document.getElementById(PRELOAD_ID)) {
				const pl = document.createElement("link");
				pl.id = PRELOAD_ID;
				pl.rel = "preload";
				pl.as = "image";
				pl.href = "hero-background.png";
				pl.setAttribute("fetchpriority", "high");
				document.head.appendChild(pl);
			}
			// Also cover the .webp variant that index.html may inject
			if (!document.getElementById(PRELOAD_WEBP_ID)) {
				const plw = document.createElement("link");
				plw.id = PRELOAD_WEBP_ID;
				plw.rel = "preload";
				plw.as = "image";
				plw.type = "image/webp";
				plw.href = "hero-background.webp";
				plw.setAttribute("fetchpriority", "high");
				document.head.appendChild(plw);
			}
		} else {
			// Remove preloads when navigating away so they don't linger
			document.getElementById(PRELOAD_ID)?.remove();
			document.getElementById(PRELOAD_WEBP_ID)?.remove();
		}
	}, [currentPath]);

	// ── PERF: Pre-paint viewport stamp ──
	// Runs synchronously after DOM commit but BEFORE the browser paints the
	// frame. Any .lazy-section already inside the viewport (e.g. the hero
	// sub-sections on fast connections) gets .visible stamped immediately so
	// it never flashes invisible for even one frame.
	useLayoutEffect(() => {
		// FIXED: wrapped in rAF so the above-fold visibility check runs after the
		// browser has painted the new route, preventing jank on pages with many sections.
		const raf = requestAnimationFrame(() => {
			for (const el of document.querySelectorAll(".lazy-section")) {
				const r = el.getBoundingClientRect();
				if (r.top < window.innerHeight + 200) {
					el.classList.add("visible");
				}
			}
		});
		return () => cancelAnimationFrame(raf);
	}, [currentPath]);

	// ── PERF: Intersection Observer — re-observe after each route change ──
	// rootMargin '200px' bottom pre-triggers sections 200px BEFORE they scroll into
	// view so content is already visible when the user reaches it.
	// threshold:0 fires as soon as even 1px is within the extended root.
	// No idle/timeout delay — observe immediately so above-fold sections fire at load.
	useEffect(() => {
		const io = new IntersectionObserver(
			(entries) => {
				for (const e of entries) {
					if (!e.isIntersecting) continue;
					e.target.classList.add("visible");
					io.unobserve(e.target);
				}
			},
			{ rootMargin: "0px 0px 200px 0px", threshold: 0 },
		);

		for (const el of document.querySelectorAll(".lazy-section:not(.visible)")) {
			io.observe(el);
		}

		return () => {
			io.disconnect();
		};
	}, [currentPath]);

	const navigate = useCallback((path) => {
		// Guard: no-op if already on this path — prevents duplicate history entries
		// and spurious GA4 page_view events when clicking an active nav link.
		if (path === currentPathRef.current) return;
		// Save scroll of the current page keyed by its history index.
		scrollPositions.current[historyIdxRef.current] = window.scrollY;
		// Assign a new, higher index to this forward entry.
		historyCounter.current += 1;
		const newIdx = historyCounter.current;
		historyIdxRef.current = newIdx;
		// Forward navigation always starts at the top.
		window.scrollTo({ top: 0, behavior: "instant" });
		window.history.pushState({ path, idx: newIdx }, "", `#${path}`);
		setCurrentPath(path);
		// GA4: pushState does NOT fire popstate, so we track every navigation here.
		// trackPageView is a module-level function defined in the analytics block above.
		trackPageView(path);
		// AUDIT FIX: move focus to main content after navigation for a11y
		setTimeout(() => document.getElementById("main-content")?.focus(), 100);
		// Announce route change to screen readers. The guard at the top of this
		// function already returned early when path === currentPathRef.current,
		// so we can announce unconditionally here.
		const pageName =
			path === "/"
				? "Home"
				: path
						.replace(/\/+$/, "")
						.replace(/^\//, "")
						.replace(/\//g, " — ")
						.replace(/-/g, " ");
		setRouteAnnouncement(`Navigated to ${pageName} page`);
		// Cancel any previous clear timer before starting a new one — prevents
		// rapid navigation from stacking timers that blank a newer announcement.
		clearTimeout(announceClearTimer.current);
		announceClearTimer.current = setTimeout(() => setRouteAnnouncement(""), 1500);
	}, []);

	// Route resolution — memoized so unrelated state changes (e.g. routeAnnouncement)
	// don't cause React to unmount/remount the entire page subtree.
	const page = useMemo(() => {
		if (currentPath.startsWith("/product/"))
			return (
				<ProductDetailPage
					productId={currentPath.split("/")[2]}
					navigate={navigate}
				/>
			);
		if (currentPath.startsWith("/blog/"))
			return (
				<BlogPostPage
					slug={currentPath.replace("/blog/", "")}
					navigate={navigate}
				/>
			);
		if (currentPath.startsWith("/industry/"))
			return (
				<IndustryDetailPage
					industryId={currentPath.split("/")[2]}
					navigate={navigate}
				/>
			);
		if (currentPath.startsWith("/service/"))
			return (
				<ServiceDetailPage
					serviceId={currentPath.split("/")[2]}
					navigate={navigate}
				/>
			);
		if (currentPath.startsWith("/project/"))
			return (
				<ProjectDetailPage
					projectId={currentPath.split("/")[2]}
					navigate={navigate}
				/>
			);
		switch (currentPath) {
			case "/":
				return <HomePage navigate={navigate} />;
			case "/about":
				return <AboutPage navigate={navigate} />;
			case "/blog":
				return <BlogPage navigate={navigate} />;
			case "/services":
				return <ServicesPage navigate={navigate} />;
			case "/products":
				return <ProductsPage navigate={navigate} />;
			case "/industries":
				return <IndustriesPage navigate={navigate} />;
			case "/projects":
				return <ProjectGalleryPage navigate={navigate} />;
			case "/contact":
				return <ContactPage navigate={navigate} />;
			case "/downloads":
				return <DownloadsPage navigate={navigate} />;
			default:
				return <NotFoundPage navigate={navigate} />;
		}
	}, [currentPath, navigate]);

	return (
		<CurrencyProvider>
			<div className="font-sans min-h-screen flex flex-col bg-white selection:bg-blue-600 selection:text-white text-[#111827]">
				{/* AUDIT FIX: aria-live region for screen reader route change announcements */}
				<div
					className="sr-only"
					aria-live="assertive"
					aria-atomic="true"
					role="status"
				>
					{routeAnnouncement}
				</div>
				<Navbar currentPath={currentPath} navigate={navigate} />
				<div className="flex-1 flex flex-col">
					<ErrorBoundary>
						<Suspense
							fallback={
								<div className="flex-1 flex items-center justify-center min-h-[60vh]">
									<span className="sr-only">Loading…</span>
								</div>
							}
						>
							{page}
						</Suspense>
					</ErrorBoundary>
				</div>
				<DigitalProfilesStrip />
				<Footer navigate={navigate} />
				{/* On mobile, product detail pages render their own sticky CTA bar,
			    so hide the floating WhatsApp FAB there to avoid overlap. */}
				<div
					className={
						currentPath.startsWith("/product/") ? "md:block hidden" : ""
					}
				>
					<FloatingButtons />
				</div>
				<BackToTopButton />

				{/* Exit-intent review popup: fixed overlay, zero layout impact.
			    Excluded paths (contact, product, service) handled by POPUP_EXCLUDED_PATHS above.
			    minTimeMs lowered to 2 min and scrollPct to 40% to catch engaged visitors.
			    Both popup and form are lazy-loaded — only fetched when exit intent fires. */}
				{showExitPopup && (
					<Suspense fallback={null}>
						<ExitIntentReviewPopup
							ReviewForm={KeshavReviewForm}
							minTimeMs={120_000}
							idleMs={90_000}
							scrollPct={40}
							navigate={navigate}
						/>
					</Suspense>
				)}
			</div>
		</CurrencyProvider>
	);
}